def rand_date(y1, m1, y2, m2):
    a = D(y1, m1, 1); b = D(y2, m2, 28); return a + TD(days=rint(0, (b - a).days))
def add_months(d, m):
    y = d.year + (d.month - 1 + m) // 12; mo = (d.month - 1 + m) % 12 + 1
    last = calendar.monthrange(y, mo)[1]; return D(y, mo, min(d.day, last)), d.day > last
def add_business_days(d, n, holidays=()):
    while n > 0:
        d += TD(days=1)
        if d.weekday() < 5 and d not in holidays: n -= 1
    return d
def sig3(x):
    if x == 0: return '0'
    e = math.floor(math.log10(abs(x))); p = 2 - e; return f"{round(x, p):.{max(p, 0)}f}"

# ------------------------------------------------------------------ rendering (JSON / YAML-ish / prose / tables)
def yaml_ish(d, ind=0):
    out = []
    for k, v in d.items():
        if isinstance(v, dict):
            out.append(' ' * ind + f"{k}:"); out.append(yaml_ish(v, ind + 2))
        elif isinstance(v, list):
            out.append(' ' * ind + f"{k}:")
            for x in v:
                if isinstance(x, dict):
                    lines = yaml_ish(x, ind + 4).split('\n'); lines[0] = ' ' * (ind + 2) + '- ' + lines[0].strip()
                    out.extend(lines)
                else: out.append(' ' * (ind + 2) + f"- {x}")
        else: out.append(' ' * ind + f"{k}: {v}")
    return '\n'.join(out)
def prose_record(d):
    parts = []
    for k, v in d.items():
        kk = k.replace('_', ' ').capitalize()
        if isinstance(v, dict): parts.append(f"{kk}: " + '; '.join(f"{a.replace('_', ' ')} {b}" for a, b in v.items()) + '.')
        elif isinstance(v, list): parts.append(f"{kk}: " + '; '.join(str(x) if not isinstance(x, dict) else ', '.join(f"{a} {b}" for a, b in x.items()) for x in v) + '.')
        else: parts.append(f"{kk}: {v}.")
    return '\n'.join(parts)
def kv_table(d):
    rows = [(k.replace('_', ' '), v if not isinstance(v, (dict, list)) else json.dumps(v, ensure_ascii=False)) for k, v in d.items()]
    w = max(len(str(k)) for k, _ in rows)
    return '| ' + 'Field'.ljust(w) + ' | Value |\n|' + '-' * (w + 2) + '|-------|\n' + '\n'.join(f"| {str(k).ljust(w)} | {v} |" for k, v in rows)
def render_record(d, layout=None):
    layout = layout or pick(['json', 'yaml', 'prose', 'table'])
    if layout == 'json': return json.dumps(d, ensure_ascii=False, indent=1)
    if layout == 'yaml': return yaml_ish(d)
    if layout == 'prose': return prose_record(d)
    return kv_table(d)
def md_table(cols, rows):
    w = [max(len(str(c)), *(len(str(r[i])) for r in rows)) for i, c in enumerate(cols)]
    line = lambda r: '| ' + ' | '.join(str(x).ljust(w[i]) for i, x in enumerate(r)) + ' |'
    return '\n'.join([line(cols), '|' + '|'.join('-' * (x + 2) for x in w) + '|'] + [line(r) for r in rows])
def pipe_rows(rows): return '\n'.join(' | '.join(str(x) for x in r) for r in rows)
def note(kind, text):
    forms = {'draft': [f'Trainee reviewer\'s draft: "{text}"', f'First-pass note ({initials()}): "{text}"', f'Handler\'s working note: "{text}"',
                       f'Junior analyst, preliminary view: "{text}"'],
             'chat': [f'Chat, #ops: "{text}"', f'Team channel message: "{text}"', f'Slack thread: "{text}"'],
             'tool': [f'System summary line: "{text}"', f'Auto-generated pre-fill: "{text}"', f'Dashboard banner: "{text}"'],
             'customer': [f'Customer wrote: "{text}"', f'Requester\'s comment: "{text}"', f'Claimant states: "{text}"'],
             'lead': [f'Team lead: "{text}"', f'Supervisor\'s reminder: "{text}"']}
    return pick(forms[kind])
def para(*lines): return '\n'.join(lines)

# ------------------------------------------------------------------ rows and balancing
def row(state, instructions, criteria, expected, qtype, bal=None):
    assert expected in criteria, (expected, list(criteria))
    if not isinstance(state, str): state = json.dumps(state, ensure_ascii=False, indent=1)
    return dict(type=qtype, state=state, instructions=instructions, criteria=criteria, expected=str(expected), bal=bal or str(expected))
def noul(state, instructions, true_desc, false_desc, truth, bal=None):
    crit = {'false': false_desc, 'true': true_desc} if chance(.5) else {'true': true_desc, 'false': false_desc}
    return row(state, instructions, crit, 'true' if truth else 'false', 'noul', bal)
def score(state, instructions, levels, idx, bal=None):
    return row(state, instructions, {str(i): t for i, t in enumerate(levels)}, str(idx), 'score', bal)
def choice(state, instructions, options, expected, bal=None):
    keys = shuffled(options) if chance(.5) else sorted(options)
    return row(state, instructions, {k: options[k] for k in keys}, expected, 'choice', bal)
def balanced(gen, n, tries=8):
    buckets = collections.defaultdict(list); made = 0
    for _ in range(n * tries):
        try: r = gen()
        except AssertionError: r = None
        if r is None: continue
        buckets[r['bal']].append(r); made += 1
        if made >= n * tries: break
    out, keys, i = [], sorted(buckets), 0
    while len(out) < n and any(buckets.values()):
        k = keys[i % len(keys)]; i += 1
        if buckets[k]: out.append(buckets[k].pop())
    return out

