def lp_procurement():
    co = pick(COMPANIES); cur = pick(['EUR', 'USD', 'GBP']); levels = pick(LEVEL_SETS); ctx = lp_ctx(co); fmt = pick(DATE_FMTS)
    b = pick([(10000, 50000, 150000, 500000), (5000, 25000, 100000, 250000), (20000, 75000, 200000, 1000000), (25000, 100000, 250000, 750000)])
    req = rand_date(2026, 3, 2027, 6); win0 = pick([60, 90]); amended = chance(.6); win1 = pick([120, 180]) if amended else win0
    eff = req + TD(days=rint(-150, 60)); window = win1 if (amended and eff <= req) else win0
    annual = round(math.exp(rr(math.log(2500), math.log(320000))) / 100) * 100; ren = pick([0, 1, 2, 2, 3]); term = pick([12, 12, 24, 36])
    onetime = sample([('implementation', round(annual * rr(.1, .5) / 100) * 100), ('training', round(rr(800, 6000) / 100) * 100), ('data migration', round(rr(2000, 15000) / 100) * 100), ('onboarding', round(rr(500, 4000) / 100) * 100)], rint(0, 3))
    disc = pick(['none', 'conditional', 'unconditional']); disc_pct = pick([5, 8, 10, 15])
    rel_days = rint(5, 260); rel_amt = round(rr(0.05, 0.6) * max(annual, 8000) / 100) * 100; rel_included = rel_days <= window
    sup = pick(SUPPLIERS); sup_like = sup.split()[0] + pick(['line', 'wave', 'tec']) + ' ' + pick(['Consulting', 'Services', 'Partners'])
    tcv = annual * (term // 12) * (1 + ren) + sum(a for _, a in onetime) - (annual * disc_pct / 100 if disc == 'unconditional' else 0)
    combined = tcv + (rel_amt if rel_included else 0)
    lvl = sum(combined > x for x in b)
    naive = sum((annual * (1 - disc_pct / 100 if disc != 'none' else 1)) > x for x in b)
    bands = [f"up to and including {cur} {b[0]:,}", f"above {cur} {b[0]:,} up to and including {cur} {b[1]:,}", f"above {cur} {b[1]:,} up to and including {cur} {b[2]:,}", f"above {cur} {b[2]:,} up to and including {cur} {b[3]:,}", f"above {cur} {b[3]:,}"]
    pol = pick(['GP-02', 'PP-7', 'PROC-1', 'AP-14']); pr = ref('PR')
    core = [('Scope', "{n}.1 This {doc} governs the purchase of goods and services by {company} and its subsidiaries, other than payroll, taxes and intercompany charges.\n{n}.2 Its objectives are value for money, segregation of duties and a complete approval trail.".format(**ctx)),
            ('Definitions', f"{{n}}.1 \"Total Contract Value\" or \"TCV\": everything {co} may become obliged to pay the supplier over the contract's maximum possible duration, namely (a) recurring fees for the initial term, (b) recurring fees for every renewal or extension period that {co} can trigger unilaterally or that occurs automatically unless cancelled, (c) one-time fees such as implementation, training, migration or onboarding, and (d) committed minimum volumes. TCV excludes VAT. Where renewal fees are not fixed, the last year of the initial term is used.\n{{n}}.2 Discounts. A discount reduces TCV only when it is unconditional and written into the order form to be signed. Conditional, time-limited or verbal offers (for example \"{disc_pct}% off if signed by month end\") are disregarded even if the requester intends to meet the condition.\n{{n}}.3 \"Related Purchase\": a purchase from the same supplier or its affiliates for the same or a directly related business purpose. A supplier with a similar name but different ownership is not the same supplier.\n{{n}}.4 \"Requester\": the employee who raises the request in {ctx['system']}."),
            ('Approval levels (by TCV)', '\n'.join(f"{{n}}.{i + 1} Level {i + 1} — {bands[i]}: {t}." for i, (k, t) in enumerate(levels)) + "\n{n}.6 Each level includes the levels below it; the \"required approval level\" is the highest level the purchase reaches."),
            ('Aggregation', f"{{n}}.1 Requests must not be split to avoid a higher level.\n{{n}}.2 When determining the level, the TCV of the request is added to the TCV of all Related Purchases approved in the {win0} calendar days before the submission date. The combined figure sets the level, whether or not the earlier purchase was deliberately split."),
            ('Competitive quotes', f"{{n}}.1 Purchases with TCV above {cur} {b[0] * 2:,} require three written quotes or a sourcing waiver.\n{{n}}.2 Call-offs under framework agreements listed in the annex need no further quotes."),
            ('Other reviews', "{n}.1 Information Security review for any software, SaaS or hosting service, independent of approval level.\n{n}.2 Legal review for non-standard liability terms or a term longer than 36 months.")]
    amend_txt = [f"AMENDMENT {pol}/A2 (effective {fmt(eff)}, for requests submitted from that date)", f"(1) In the aggregation clause, \"{win0} calendar days\" is replaced by \"{win1} calendar days\".", "(2) The approval thresholds and the definition of TCV are unchanged.", f"(3) Requesters must record the cancellation notice period of auto-renewing subscriptions in {ctx['system']}."] if amended else [f"No amendments to {pol} are in force. (A draft amendment to the aggregation window was circulated but not approved.)"]
    ex_tcv = [round(rr(0.5, 1.5) * b[i] / 100) * 100 for i in (0, 2)]
    examples = [f"E.{j + 1} A request with combined TCV {cur} {v:,} reaches Level {sum(v > x for x in b) + 1} ({levels[sum(v > x for x in b)][1]})." for j, v in enumerate(ex_tcv)]
    faq = [f"Q: The renewal is optional for us — does it count? A: Yes if {co} can trigger it unilaterally or it renews unless cancelled; only renewals that require a new signed order are excluded.",
           "Q: Our supplier promised a discount by e-mail. A: Disregarded unless written into the order form as unconditional."]
    order = {'supplier': sup, 'initial_term_months': term, 'annual_fee': money(annual, cur) + ' excl. VAT', 'renewal': (f"renews automatically for up to {ren} further {term}-month period(s) at the same fee unless {co} gives 60 days' notice" if ren else 'no automatic renewal; any extension requires a new signed order form'),
             'one_time_fees': {k: money(a, cur) for k, a in onetime} or 'none', 'discount': {'none': 'none stated', 'conditional': f"{disc_pct}% off the first-year fee if signed by {fmt(req + TD(days=rint(10, 40)))} — offered by e-mail, not in the order form", 'unconditional': f"{disc_pct}% off the first-year fee, unconditional, printed in the order form"}[disc],
             'submitted': fmt(req), 'requester': person(), 'description': pick(['demand-forecasting SaaS', 'contract lifecycle platform', 'fleet telematics subscription', 'e-learning platform', 'security monitoring service'])}
    hist = [f"{ref('PR')} — {sup}, approved {fmt(req - TD(days=rel_days))} ({rel_days} days before submission), TCV {money(rel_amt, cur)}: {pick(['pilot connector licence', 'proof-of-concept phase', 'data loading services', 'initial workshop'])} for the same platform.",
            f"{ref('PR')} — {sup_like} (different ownership, confirmed by Supplier Master Data), approved {fmt(req - TD(days=rint(5, 40)))}, TCV {money(round(rr(3000, 30000)), cur)}: unrelated process consulting."]
    draft = note('customer', f"Annual fee is {money(annual * (1 - disc_pct / 100 if disc != 'none' else 1), cur)}, which is within the {levels[naive][1]} band, so please route to Level {naive + 1}.") if naive != lvl or chance(.3) else note('lead', 'Check the aggregation window and the renewal terms before routing.')
    case = para(f"PURCHASE REQUEST {pr}", render_record(order), '', f"{ctx['system']} history — supplier and similar names:", *hist, '', draft, f"Treasury: all amounts already in {cur}.")
    state = assemble(f"{co.upper()} — PROCUREMENT {ctx['doc'].upper()} {pol} (consolidated extract) WITH AMENDMENT AND REQUEST {pr}", core, ctx, f"PART III — {pr}", case, faq=faq, examples=examples, changelog=amend_txt)
    instr = pick([f"Determine the required approval level for {pr} under {pol} as amended.", f"Which approval level does {pr} reach under {pol}, taking the amendment into account?",
                  f"Route {pr}: identify the highest approval level it requires under {pol}.", f"Applying {pol} (with any amendment in force), what is the required approval level for {pr}?"])
    opts = {k: f"The request tops out at Level {i + 1}, {t}: combined TCV {bands[i]}." for i, (k, t) in enumerate(levels)}
    return choice(state, instr, opts, levels[lvl][0], bal=str(lvl))

def lp_returns():
    co = pick(COMPANIES); cur = pick(['EUR', 'USD']); ctx = lp_ctx(co); fmt = pick(DATE_FMTS); pol = pick(['CRP-6', 'RET-2', 'RP-11'])
    delivery = rand_date(2026, 4, 2027, 3); dispatch = delivery - TD(days=rint(2, 7)); window = pick([30, 45]); rma = delivery + TD(days=rint(window - 12, window + 14))
    custom = chance(.3); x_code = pick(['X-CC', 'X-FW', 'X-HT']); defective_claim = chance(.8); fault_confirmed = defective_claim and chance(.45)
    powered = rint(0, 140); damage = chance(.15); accessories = chance(.85); unused = powered <= 72 and not damage and accessories
    tier_now = pick(['Gold', 'Silver', 'Silver', 'Registered']); tier_shown = 'Gold' if tier_now != 'Gold' and chance(.6) else tier_now
    discontinued_days = rint(20, 200) if chance(.25) else None; disc_window = 90
    within = (rma - delivery).days <= window
    if custom: verdict = 'repair_or_replace' if fault_confirmed else 'reject_return'
    elif fault_confirmed: verdict = 'full_credit' if within else 'repair_or_replace'
    elif within and unused: verdict = 'full_credit' if (tier_now == 'Gold' or (discontinued_days is not None and discontinued_days <= disc_window)) else 'credit_less_restocking'
    else: verdict = 'reject_return'
    qty = rint(3, 20); unit = round(rr(180, 1500), 2); prod = pick(['PX-500 controller', 'RM-12 relay module', 'VS-8 valve station', 'HMI-7 panel'])
    conf = f"{prod.split()[0]}-{pick(['IO16', 'IO32'])}-{pick(['PS24', 'PS48'])}-{'FWSTD' if not custom else x_code}-{pick(['HSG1', 'HSG2'])}"
    core = [('Scope', "{n}.1 This {doc} applies to commercial returns (return for credit) by business customers buying directly from {company}. Warranty claims are handled separately and are unaffected.".format(**ctx)),
            ('Definitions', f"{{n}}.1 \"Standard Product\": a catalogue product, including one configured in the online configurator using only catalogue option codes.\n{{n}}.2 \"Custom-built Product\": a product built to customer specification. Any configuration containing an option code with the prefix X- is Custom-built.\n{{n}}.3 \"Delivery Date\": the date the carrier's proof of delivery shows the goods were delivered. Dispatch and invoice dates are not the Delivery Date.\n{{n}}.4 \"RMA Request Date\": the date a complete return request is submitted in the partner portal. Drafts are not requests.\n{{n}}.5 \"Defective\": {co}'s inspection confirms a fault in materials or workmanship present at delivery. A product returned as defective in which inspection finds no fault (\"No Fault Found\") is not Defective.\n{{n}}.6 \"Unused\": powered in an application for no more than 72 hours in total, with no physical damage, returned with all accessories."),
            ('Eligibility', f"{{n}}.1 Standard Products may be returned for credit if the RMA Request Date is no later than {window} days after the Delivery Date and the products are Unused, or are Defective.\n{{n}}.2 Custom-built Products are not returnable for credit; Defective Custom-built Products are repaired or replaced.\n{{n}}.3 Standard Products requested for return after the {window}-day window are rejected unless Defective, in which case they are repaired or replaced."),
            ('Credit and fees', f"{{n}}.1 Accepted returns are credited at the invoiced net price.\n{{n}}.2 A restocking fee of 15% is deducted for returns that are not Defective.\n{{n}}.3 The fee is waived (a) for Gold partners, (b) where the return results from a {co} error, (c) for products discontinued within {disc_window} days before the RMA Request Date.\n{{n}}.4 No other waiver is valid without the written approval of the Head of Customer Service.\n{{n}}.5 No Fault Found returns are assessed as returns that are not Defective, under the eligibility and fee clauses, as at the RMA Request Date."),
            ('Partner tiers', "{n}.1 Tiers are recalculated on the first day of each calendar quarter from the trailing 12 months of net purchases and apply from that day.\n{n}.2 Where a clause depends on tier, the tier in the ERP master record on the RMA Request Date applies. The portal header is a display refreshed monthly and is not the master record.")]
    changelog = [f"Amendment 1 (effective {fmt(delivery - TD(days=rint(30, 200)))}): configurator products with catalogue codes only are Standard; X- codes make a product Custom-built; discontinued-product waiver window set to {disc_window} days.",
                 f"Superseded {pol[:-1]}{int(pol[-1]) - 1} (for reference only): 14-day window from invoice date; 20% fee; every configurator order treated as Custom-built."]
    examples = [f"E.1 Standard product delivered day 0, RMA on day {window - 3}, inspection confirms fault: full credit.", f"E.2 Standard product, RMA on day {window + 5}, No Fault Found: rejected (outside window, not Defective).",
                f"E.3 Standard product, RMA on day {window - 10}, No Fault Found, 40 powered hours, Silver partner: credit less 15% fee."]
    rec = {'customer': f"{pick(COMPANIES)} (direct customer)", 'sales_order': ref('SO'), 'items': f"{qty} × {prod}, configuration {conf} ({'contains special engineering option ' + x_code if custom else 'all option codes are catalogue codes'})",
           'net_price': f"{money(unit, cur)} per unit, total {money(unit * qty, cur)}", 'dispatched_and_invoiced': fmt(dispatch), 'carrier_proof_of_delivery': f"delivered and signed for {fmt(delivery)}",
           'rma_request': f"submitted {fmt(rma)} ({(rma - delivery).days} days after delivery), reason: {'defective — ' + pick(['units reset under load', 'intermittent output', 'display flickers']) if defective_claim else 'no longer required'}",
           'earlier_portal_draft': f"saved {fmt(rma - TD(days=rint(1, 5)))}, not submitted" if chance(.5) else 'none',
           'inspection': (f"fault in {pick(['solder joint', 'output driver', 'power stage'])} confirmed on all units" if fault_confirmed else f"No Fault Found on all units ({pick(['customer parameter set caused resets', 'wiring error on customer side', 'no anomaly reproduced'])})") if defective_claim else 'not applicable (commercial return)',
           'condition': f"{powered} powered hours per unit in the units' log; {'scratched housings' if damage else 'no physical damage'}; accessories {'complete' if accessories else 'incomplete (mounting kits missing)'}",
           'erp_partner_tier': f"{tier_now} since {fmt(D(rma.year, ((rma.month - 1) // 3) * 3 + 1, 1))}", 'portal_header_tier': f"{tier_shown} (display last refreshed {fmt(rma - TD(days=rint(20, 70)))})",
           'catalogue_status': f"{prod} discontinued {discontinued_days} days before the RMA Request Date" if discontinued_days else f"{prod} current, no discontinuation"}
    naive = note('customer', f"As a {tier_shown} partner we expect the usual full credit.") if chance(.6) else note('draft', f"Return requested {(rma - dispatch).days} days after invoice — {'outside' if (rma - dispatch).days > window else 'inside'} the window on that basis.")
    case = para(f"RMA REQUEST {ref('RQ')} — ASSESSMENT PACK", render_record(rec), '', naive, "No approval by the Head of Customer Service is recorded on this RMA.")
    state = assemble(f"{co.upper()} — RETURNS DESK — COMMERCIAL RETURNS {ctx['doc'].upper()} {pol} WITH AMENDMENT 1", core, ctx, "CASE FILE", case, examples=examples, changelog=changelog)
    instr = pick([f"What decision must the returns desk issue on this RMA under {pol} as amended?", f"Apply {pol} (as amended) to the RMA in the case file and select the returns desk's decision.",
                  f"Under {pol} with Amendment 1, how is this return to be settled?"])
    opts = {'full_credit': 'Accept the return and credit the full invoiced net value with no restocking fee.', 'credit_less_restocking': 'Accept the return and credit the invoiced net value less the 15% restocking fee.',
            'reject_return': 'Reject the return: no credit, repair or replacement under this policy.', 'repair_or_replace': 'No credit; the units are repaired or replaced.'}
    return choice(state, instr, opts, verdict)

def lp_insurance():
    co = pick(COMPANIES); ctx = lp_ctx(co); fmt = pick(DATE_FMTS); form = pick(['HO-4', 'HP-2', 'DW-9'])
    s0 = pick([5000, 10000]); s1 = s0 + pick([5000, 10000]); ded = pick([500, 1000, 2500]); end_cut = rand_date(2025, 6, 2026, 6)
    term_start = end_cut + TD(days=rint(-200, 200)); term_start = D(term_start.year, term_start.month, min(term_start.day, 28)); loss = term_start + TD(days=rint(30, 300))
    endorsed = term_start >= end_cut; away = rint(20, 110); furnished = chance(.6); seep_days = pick([3, 7, 10, 14, 21, 35, 45]); known = chance(.3)
    vacant = not furnished
    if vacant and away > 60: verdict = 'deny_vacancy_exclusion'
    elif seep_days >= 14: verdict = ('pay_subject_to_higher_sublimit' if endorsed else 'pay_subject_to_base_sublimit') if not known else 'deny_repeated_seepage'
    else: verdict = 'pay_full_estimate_less_deductible'
    est = round(rr(8000, 30000) / 10) * 10; insured = person()
    core = [('Definitions', f"{{n}}.1 \"Concealed water\": water that escapes from within a plumbing, heating or air-conditioning system or a household appliance and remains hidden within walls, floors or ceilings, where its presence was not known to and could not reasonably have been known to an insured before the damage became visible.\n{{n}}.2 \"Repeated seepage or leakage\": continuous or repeated seepage or leakage of water over a period of 14 or more days.\n{{n}}.3 \"Unoccupied\": the dwelling contains furnishings and contents sufficient for customary occupancy but no person is living in it.\n{{n}}.4 \"Vacant\": the dwelling lacks contents sufficient for customary occupancy, whether or not a person is present."),
            ('Perils insured', "{n}.1 We insure against direct physical loss to the dwelling except as excluded. Accidental discharge of water from a plumbing system or appliance is covered subject to the exclusions and limits below, including reasonable tear-out cost to reach the source."),
            ('Exclusions', f"{{n}}.1 Repeated seepage or leakage. We do not cover loss caused by \"repeated seepage or leakage\".\n{{n}}.1.1 Exception for concealed water: this exclusion does not apply to loss caused by \"concealed water\". Our total payment for concealed-water loss in any one occurrence will not exceed ${s0:,}, including tear-out.\n{{n}}.2 Vacancy. We do not cover accidental discharge of water if the dwelling has been vacant for more than 60 consecutive days immediately before the loss.\n{{n}}.3 Wear and tear, corrosion and deterioration; however, resulting water damage to the building is covered subject to {{n}}.1 and {{n}}.2."),
            ('Conditions', f"{{n}}.1 Deductible: ${ded:,} per occurrence, applied before any sublimit.\n{{n}}.2 Loss settlement at replacement cost subject to the limits and sublimits of this policy.")]
    endorsement = f"ENDORSEMENT WX-{rint(100, 999)} CONCEALED WATER SUBLIMIT REVISION\nA. Applicability: this endorsement applies only to policy terms issued or renewed on or after {fmt(end_cut)}. For terms issued or renewed before that date, the exception in the exclusions section applies as written in the form.\nB. In the concealed-water exception, \"${s0:,}\" is replaced by \"${s1:,}\".\nC. This endorsement does not modify the vacancy exclusion."
    examples = [f"E.1 Pinhole leak active 5 days inside a wall, dwelling occupied: covered without sublimit; estimate less ${ded:,} deductible.", f"E.2 Leak active 6 weeks inside a wall, unknown to the insured, term renewed after the endorsement date: covered up to ${s1:,}.",
                f"E.3 Dwelling emptied of furniture for 90 days before a burst pipe: excluded under the vacancy exclusion."]
    facts = {'named_insured': insured, 'current_term': f"{fmt(term_start)} to {fmt(add_months(term_start, 12)[0])} (renewal of the prior term)", 'forms_attached': f"{form}; WX endorsement listed on the current declarations",
             'loss_reported': fmt(loss + TD(days=rint(1, 4))), 'building_estimate': f"${est:,} (building repairs only)", 'deductible': f"${ded:,}",
             'adjuster_findings': f"{pick(['pinhole in copper supply line', 'failed dishwasher hose', 'cracked fitting behind the shower'])} inside a wall cavity; plumber estimates the leak had been active about {seep_days} days; " + (f'insured admits noticing staining about {max(2, seep_days - rint(3, 10))} days before the loss and doing nothing' if (known and seep_days >= 14) else 'no visible signs before the damage appeared; insured had no reason to suspect a leak'),
             'occupancy': f"insured away {away} consecutive days before the loss; " + ('house fully furnished, utilities on, food in the refrigerator' if furnished else 'house emptied of furniture and contents for a planned sale; only a ladder and paint tins inside')}
    naive = note('draft', f"Insured was gone {away} days, over the 60-day limit, so the vacancy exclusion should apply. Recommend denial.") if away > 60 and furnished else note('draft', f"Concealed water — apply the ${s0:,} sublimit from the form.") if endorsed and verdict.startswith('pay_subject') else note('lead', 'Please confirm which endorsement edition applies to this term.')
    case = para(f"CLAIM FILE {ref('HX', 6)}", render_record(facts), '', naive, f"Policy history: prior term issued on the {form} form; current term renewed on the date shown above.")
    state = assemble(f"{co.upper()} — HOMEOWNERS FORM {form} (EXTRACTS), ENDORSEMENTS AND CLAIM FILE", core, ctx, "ENDORSEMENT AND CLAIM FILE", endorsement + '\n\n' + case, examples=examples)
    instr = pick(["Decide how the building water-damage portion of this claim must be settled under the form and the endorsements attached to the current term.", "As coverage reviewer, determine the settlement basis for the building water damage in the claim file.",
                  "Under the policy form as modified by any applicable endorsement, how is the water-damage loss settled?"])
    opts = {'deny_repeated_seepage': 'Excluded as repeated seepage or leakage with no exception applying.', 'deny_vacancy_exclusion': 'Excluded because the dwelling was vacant for more than 60 consecutive days before the loss.',
            'pay_full_estimate_less_deductible': f'Covered without any sublimit; the estimate is paid less the ${ded:,} deductible.', 'pay_subject_to_base_sublimit': f'Covered but capped by the concealed-water sublimit of ${s0:,}.', 'pay_subject_to_higher_sublimit': f'Covered but capped by the revised concealed-water sublimit of ${s1:,}.'}
    return choice(state, instr, opts, verdict)

def lp_licence():
    co = pick(COMPANIES); ctx = lp_ctx(co); fmt = pick(DATE_FMTS); sw = pick(['Tessera CAD Pro', 'Helix PLM', 'Orbit Analytics Suite', 'Marlin Design Studio'])
    M = pick([D(2026, 8, 31), D(2026, 12, 31), D(2027, 6, 30)])
    base = rint(70, 140); dups = rint(0, 3); leave = [(rint(40, 200)) for _ in range(rint(0, 2))]; disabled = [(rint(1, 6), rint(5, 80)) for _ in range(rint(1, 3))]
    shared = rint(0, 8); contractors = rint(0, 10); contractor_conf = chance(.4); svc_interactive = chance(.5); qa_testers = rint(0, 6); qa_registered = chance(.5)
    named = base - dups + sum(1 for d in leave if d < 90) + sum(c for c, days in disabled if days < 30) + shared + (0 if contractor_conf else contractors) + (1 if svc_interactive else 0) + (0 if qa_registered else qa_testers)
    band = pick([0, 1, 2, 3]); short = {0: rint(-8, 0), 1: rint(1, 5), 2: rint(6, 15), 3: rint(16, 30)}[band]
    held = named - short; of1 = max(20, held - rint(0, 30)); of2 = held - of1; of3 = rint(5, 20)
    core = [('Definitions', f"{{n}}.1 \"Licence\": a named-user subscription; one Licence permits one Named User on any number of devices.\n{{n}}.2 \"Named User\": an individual human authorised to access the Software with an active account on the Measurement Date. An individual is one Named User however many accounts they hold.\n{{n}}.3 Shared accounts: each individual who used a shared account during the three months ending on the Measurement Date is a Named User.\n{{n}}.4 Service accounts used solely by software processes are not Named Users; an individual who logs in interactively through a service account during those three months is a Named User.\n{{n}}.5 \"Active account\": any account existing on the Measurement Date unless disabled or deleted at least 30 days before it.\n{{n}}.6 \"Measurement Date\": {fmt(M)} and the same day each year."),
            ('Third parties', "{n}.1 Contractors using the Software for the Licensee's purposes are Named Users of the Licensee unless they use their own licences under their own agreement and the Licensee holds written confirmation of this from the vendor."),
            ('True-up', "{n}.1 Licences held on the Measurement Date are the Licences under all Order Forms whose licence start date is on or before the Measurement Date.\n{n}.2 A shortfall (Named Users minus Licences held, if positive) is purchased at list price with 12 months of back-dated fees.\n{n}.3 Shortfall bands for reporting: none; 1 to 5; 6 to 15; more than 15."),
            ('Amendments', "{n}.1 Amendment 1: Named Users on continuous leave of absence of 90 days or more on the Measurement Date, whose accounts were not used during the leave, are not counted.\n{n}.2 Amendment 2: accounts existing only in a Non-Production Environment registered with the vendor are not counted for any Measurement Date on which the registration was in effect. Registration takes effect on the date the vendor confirms receipt of the registration form. Accounts in an unregistered environment count like production accounts, each individual once across all environments.")]
    inv = [f"D1 Production tenant: {base} enabled named accounts belonging to employees. Identity management shows {dups} engineer(s) each holding two accounts (a standard and an -admin account)." + (" All other accounts belong to different individuals." if dups else ""),
           *[f"D2.{i + 1} One employee on continuous {pick(['parental', 'sick', 'sabbatical'])} leave for {d} days as at the Measurement Date; account unused during the leave and never disabled." for i, d in enumerate(leave)],
           *[f"D3.{i + 1} {c} leaver account(s) disabled {days} days before the Measurement Date (still present in the tenant); none of these individuals has another account." for i, (c, days) in enumerate(disabled)],
           f"D4 Shared workshop account: badge-to-terminal records for the three months ending on the Measurement Date show use by {shared} distinct technicians, none of whom holds a named account." if shared else "D4 No shared accounts.",
           (f"D5 {contractors} contractor accounts (outsourcing partner). The partner holds its own {sw} subscription; " + ("the vendor's written confirmation under the third-party clause is on file." if contractor_conf else "no written confirmation from the vendor is on file.")) if contractors else "D5 No contractor accounts.",
           f"D6 Service accounts svc-1..svc-3 (render farm): svc-1 and svc-3 API sessions only; svc-2 " + (f"shows {rint(4, 20)} interactive desktop logins in the last three months from a workstation assigned to an intern who holds no named account." if svc_interactive else "API sessions only."),
           (f"D7 QA tenant: {qa_testers} tester accounts belonging to individuals with no production account (plus some duplicates of production users). Registration form for the QA tenant confirmed by the vendor " + (f"{rint(20, 120)} days before the Measurement Date." if qa_registered else f"{rint(2, 20)} days AFTER the Measurement Date.")) if qa_testers else "D7 No QA tenant.",
           f"D8 Training tenant, registered {rint(100, 300)} days before the Measurement Date: {rint(5, 15)} accounts, all belonging to individuals who also hold production accounts."]
    orders = [f"OF-1 ({fmt(M - TD(days=rint(700, 1200)))}): {of1} Licences, start date on signature.", f"OF-2 ({fmt(M - TD(days=rint(100, 600)))}): {of2} additional Licences, licence start date {fmt(M - TD(days=rint(30, 90)))}.",
              f"OF-3 (signed {fmt(M - TD(days=rint(2, 10)))}): {of3} additional Licences, licence start date {fmt(M + TD(days=rint(1, 15)))}."]
    naive_count = base + (1 if shared else 0)
    naive = note('draft', f"Working assumption from last year's method sheet: count enabled named production accounts plus shared accounts as one each; test tenants excluded. That gives {naive_count} Named Users against {of1 + of2 + of3} Licences.")
    case = para(f"ACCOUNT INVENTORY AS OF {fmt(M)}", *inv, '', 'ORDER FORMS', *orders, '', naive)
    state = assemble(f"{co.upper()} — IT ASSET MANAGEMENT — {sw.upper()} ENTERPRISE LICENCE AGREEMENT (EXTRACTS) AND TRUE-UP WORKSHEET", core, ctx, "TRUE-UP WORKSHEET", case)
    instr = pick([f"Under the agreement as amended, what is {co}'s licence position for the {fmt(M)} Measurement Date? Output the level index.", f"Determine the true-up shortfall band for the Measurement Date {fmt(M)} under the agreement and its amendments.",
                  "Count Named Users and Licences held per the agreement (as amended) and select the shortfall band."])
    levels = ['No shortfall: Named Users are within the Licences held on the Measurement Date', 'Short by 1 to 5 Licences', 'Short by 6 to 15 Licences', 'Short by more than 15 Licences']
    return score(state, instr, levels, band)

def lp_relief():
    co = pick(COMPANIES); ctx = lp_ctx(co); fmt = pick(DATE_FMTS); cur = pick(['GBP', 'EUR']); pol = pick(['PR-6', 'FS-3', 'HR-9'])
    app = rand_date(2026, 7, 2027, 5); amended = chance(.7); base_months = 6 if amended else 12; amend_eff = app - TD(days=rint(10, 200))
    truth = chance(.5); fail = None if truth else pick(['drop', 'dpd', 'frequency', 'property', 'affordability'])
    hardship = app - TD(days=rint(150, 260)); hm_ = D(hardship.year, hardship.month, 1)
    pay = round(rr(900, 1900)); months = []
    base_inc = round(rr(4000, 7500) / 50) * 50
    for i in range(base_months): m, _ = add_months(hm_, -(base_months - i)); months.append([m, base_inc])
    bonus_i = rint(0, base_months - 1); bonus = round(rr(1500, 4000) / 100) * 100; months[bonus_i][1] += bonus
    drop_target = rr(0.26, 0.38) if fail != 'drop' else rr(0.18, 0.249)
    cur_inc = round(base_inc * (1 - drop_target)); k = 0; m = hm_
    cur_months = []
    while m < D(app.year, app.month, 1):
        cur_months.append([m, cur_inc + rint(-60, 60) if k else round(base_inc * (1 - drop_target * 0.6))]); m, _ = add_months(m, 1); k += 1
    cur_avg = sum(v for _, v in cur_months[-2:]) / 2; drop = 1 - cur_avg / base_inc
    dpd = rint(20, 60) if fail != 'dpd' else rint(61, 75)
    prev_start = app - TD(days=rint(760, 1100)) if fail != 'frequency' else app - TD(days=rint(600, 729)); prev_end = prev_start + TD(days=rint(150, 185))
    owner_occ = fail != 'property'; proposed = round(pay * (rr(0.52, 0.7) if fail != 'affordability' else rr(0.35, 0.49)))
    truth = drop >= 0.25 and dpd <= 60 and (app - prev_start).days >= 730 and owner_occ and proposed >= 0.5 * pay
    core = [('Definitions', f"{{n}}.1 \"Gross Monthly Income\": household income before tax in a calendar month, including salary, self-employed drawings, pensions and regular benefits. It excludes one-off payments: annual or discretionary bonuses, redundancy lump sums, gifts and tax refunds.\n{{n}}.2 \"Hardship Month\": the calendar month in which the income-reducing event occurred.\n{{n}}.3 \"Baseline Income\": the average Gross Monthly Income over the full calendar months immediately before the Hardship Month (number of months per the eligibility clause).\n{{n}}.4 \"Current Income\": the average Gross Monthly Income over the two most recent full calendar months before the application date.\n{{n}}.5 \"Days Past Due\": days since the oldest unpaid contractual payment fell due, on the application date."),
            ('Eligibility — all conditions must be met', f"{{n}}.1 (a) Current Income is at least 25% lower than Baseline Income, with Baseline Income calculated over the 12 full calendar months before the Hardship Month.\n{{n}}.1 (b) Days Past Due is 60 or fewer.\n{{n}}.1 (c) No relief plan has started in the 24 months before the application date, measured from the start date of the previous plan.\n{{n}}.1 (d) The property is the household's owner-occupied main residence.\n{{n}}.1 (e) The proposed reduced payment is at least 50% of the contractual payment.\n{{n}}.2 Handlers may not waive any condition; where one fails, standard arrears options are offered instead."),
            ('Evidence', "{n}.1 Gross figures from payslips are used. Net pay from bank statements is used only as a consistency check and never as the income figure.")]
    changelog = [f"Amendment {pol}/A1 (effective {fmt(amend_eff)}, for applications received from that date): in the eligibility clause (a), \"12 full calendar months\" is replaced by \"6 full calendar months\". The 25% threshold and the income definition are unchanged."] if amended else [f"No amendment to {pol} is in force."]
    inc_lines = [f"- {MONTHS[m.month - 1]} {m.year}: {cur} {v:,}" + (f" (includes annual bonus of {cur} {bonus:,}, shown separately on the payslip)" if i == bonus_i else '') for i, (m, v) in enumerate(months)] + [f"- {MONTHS[m.month - 1]} {m.year}: {cur} {v:,}" for m, v in cur_months]
    naive_base = sum(v for _, v in months) / base_months; naive_drop = 1 - cur_avg / naive_base
    draft = note('draft', f"Baseline ({base_months} months) {cur} {naive_base:,.0f}; current {cur} {cur_avg:,.0f}; drop {naive_drop * 100:.1f}% — {'over' if naive_drop >= .25 else 'under'} 25%. DPD {dpd}. Previous plan started {fmt(prev_start)}. Proposed {cur} {proposed:,} is {proposed / pay * 100:.0f}% of {cur} {pay:,}. Recommend {'approve' if naive_drop >= .25 and dpd <= 60 else 'decline'}.")
    facts = para(f"Borrowers: {person()} and {person()} (joint mortgage).", f"Property: {'owner-occupied main residence since ' + str(rint(2012, 2022)) if owner_occ else 'buy-to-let flat; borrowers live elsewhere'}.",
                 f"Contractual monthly payment: {cur} {pay:,}. Application date: {fmt(app)} (complete). Proposed reduced payment: {cur} {proposed:,} for six months.",
                 f"Hardship event: {pick(['hours reduced', 'redundancy of one borrower', 'long-term sickness'])} with effect from {fmt(hardship)}. Hardship Month: {MONTHS[hm_.month - 1]} {hm_.year}.", "Household gross income by month (from payslips):", *inc_lines,
                 f"Arrears: Days Past Due on the application date: {dpd}.", f"Previous forbearance: relief plan started {fmt(prev_start)}, ended {fmt(prev_end)}, completed.", draft, note('lead', 'Check the income definitions and the amendment before approving.'))
    state = assemble(f"{co.upper()} — COLLECTIONS — PAYMENT RELIEF {ctx['doc'].upper()} {pol} (EXTRACT), AMENDMENT AND APPLICATION FILE", core, ctx, f"APPLICATION FILE {ref('PRA', 5)}", facts, changelog=changelog)
    instr = pick([f"Under {pol} as amended, is this application eligible for a Payment Relief Plan?", f"Applying every eligibility condition of {pol} (with the amendment in force), does the application qualify?",
                  f"Is the household in the application file eligible for relief under {pol}?"])
    return noul(state, instr, "Every eligibility condition (as amended) is met.", "At least one eligibility condition (as amended) is not met.", truth)

def lp_incident():
    co = pick(COMPANIES); ctx = lp_ctx(co); fmt = pick(DATE_FMTS); rb = pick(['ISR v6', 'SEV-STD 3', 'IM-2'])
    active = rint(2500, 6000); pct = pick([rr(0.2, 0.9), rr(1.1, 9.5), rr(10.5, 39), rr(41, 60)]); affected = round(active * pct / 100)
    any_fail = affected + rint(50, 400); ent = rint(0, 4); trial = rint(0, 2); dur = pick([rint(60, 235), 240, rint(241, 400)]); wa_min = pick([None, rint(5, 29), rint(31, 90)])
    payment = chance(.15); dataloss = pick(['none', 'rpo', 'manual'])
    share = affected / active * 100
    base = 3 if (share > 40 or dataloss == 'unrecoverable') else 2 if (share > 10 or ent >= 3) else 1 if (share >= 1 or ent >= 1) else 0
    if payment: base = max(base, 2)
    if dataloss == 'manual': base = max(base, 2)
    sev = base
    if dur > 240: sev = min(3, sev + 1)
    if wa_min is not None and wa_min <= 30: sev = max(0, sev - 1)
    if ent >= 1: sev = max(sev, 1)
    core = [('Definitions', "{n}.1 \"Active tenant\": sent at least one API request in the 7 days before the incident.\n{n}.2 \"Affected tenant\": an active tenant with more than 5% failed requests in at least one 10-minute window. Tenants with some failures below that rate in every window are not affected.\n{n}.3 \"Enterprise tenant\": on an Enterprise plan with a signed master agreement. Enterprise Trial (evaluation) tenants are not Enterprise tenants.\n{n}.4 \"Payment processing\": authorisation, capture, refund and payout APIs. Invoicing, documents, reporting and dashboards are not payment processing.\n{n}.5 \"Incident duration\": from the start of the first 10-minute window meeting the failure criterion to the end of the last such window; alerting and verification times are excluded.\n{n}.6 \"Workaround\": a documented alternative communicated to affected tenants allowing them to complete the operation.\n{n}.7 Data restored automatically from a log or archive with at most 15 minutes of data affected is \"recoverable within RPO\"."),
            ('Base severity', "{n}.1 SEV-1: more than 40% of active tenants affected, or unrecoverable data loss.\n{n}.2 SEV-2: more than 10% and up to 40% affected, or 3 or more Enterprise tenants affected.\n{n}.3 SEV-3: at least 1% and up to 10% affected, or 1 or 2 Enterprise tenants affected.\n{n}.4 SEV-4: below 1% affected and no Enterprise tenant affected.\n{n}.5 The highest resulting severity is the base severity.\n{n}.6 Payment processing floor: payment processing degraded for 15 minutes or more is at least SEV-2 before adjustments.\n{n}.7 Data recoverable only by manual reconstruction is at least SEV-2 before adjustments."),
            ('Adjustments (in this order)', "{n}.1 Duration: an incident duration of more than 4 hours raises the severity one level.\n{n}.2 Workaround: a Workaround available to all affected tenants for the whole duration after the first 30 minutes lowers the severity one level.\n{n}.3 Enterprise floor: after the adjustments above, an incident with at least one Enterprise tenant affected is never below SEV-3.\n{n}.4 No adjustment moves severity above SEV-1 or below SEV-4."),
            ('Review', "{n}.1 The final severity is set at the post-incident review from the facts established afterwards; the severity declared during the incident is provisional and carries no weight.")]
    t0 = rint(8 * 60, 15 * 60); t_end = t0 + dur; alert = t0 + rint(1, 9); day = rand_date(2026, 3, 2027, 4)
    ents = [f"T-{rint(10000, 19999)} {pick(COMPANIES)} — Enterprise plan, master agreement signed {rint(2022, 2026)}" for _ in range(ent)] + [f"T-{rint(10000, 19999)} {pick(COMPANIES)} — Enterprise Trial plan (evaluation), agreement under negotiation" for _ in range(trial)]
    tl = [(t0 - 8, f"Deployment of {pick(['storage client 3.4.0', 'gateway config v212', 'queue library 2.9'])} to the {pick(['Invoice', 'Document', 'Reporting'])} API pods."),
          (t0, f"–{hm(t0 + 10)} First 10-minute window in which the failure rate exceeded 5% for affected tenants."), (alert, f"Alert fired; on-call acknowledged {hm(alert + 3)}."),
          (alert + 11, f"Incident commander declared provisional SEV-{4 - min(3, sev + 1)}."),
          (t0 + 25, f"Payments API error rate {rr(6, 20):.1f}% for {rint(15, 40)} minutes; payment processing degraded." if payment else "Payments and payouts APIs checked: normal error rates throughout; no payment processing impact."),
          ((t0 + wa_min, "Workaround published on the status page and sent to every affected tenant; the alternative endpoint stayed fully available for the rest of the incident.") if wa_min is not None else (t0 + 40, "No workaround identified; tenants advised to retry.")),
          (t0 + 70, {'none': "No data loss.", 'rpo': f"{rint(3, 14)} minutes of events dropped from an in-memory queue; replayed automatically from the archive by {hm(t0 + 95)}; no manual steps.", 'manual': f"{rint(20, 50)} minutes of events lost; reconstructed manually by engineering from partner logs over the following day."}[dataloss]),
          (t_end - 10, f"–{hm(t_end)} Last 10-minute window with the failure rate above 5%."), (t_end + rint(5, 25), "All-clear declared after verification.")]
    timeline = [hm(m) + ('' if txt.startswith('–') else ' ') + txt for m, txt in sorted(tl)]
    impact = [f"Active tenants: {active:,}. Tenants with at least one failed request: {any_fail:,}. Tenants with more than 5% failed requests in at least one window: {affected:,}.",
              "Enterprise-plan tenants among the affected:", *(ents or ['none']), f"Enterprise tenants among those with failures below 5% in every window: {rint(0, 2)}."]
    ic_sev = 4 - min(3, max(sev, base) + (1 if chance(.5) else 0))
    naive = note('draft', f"Total impact about {hm(t_end + 15 - alert)} from alert to all-clear; {ent + trial} Enterprise customers affected; {any_fail:,} tenants saw errors. Suggest SEV-{ic_sev} for the review.")
    case = para(f"INCIDENT {ref('INC', 4)} — {fmt(day)}", 'TIMELINE (UTC)', *timeline, '', 'IMPACT DATA', *impact, '', naive)
    state = assemble(f"{co.upper()} — INCIDENT MANAGEMENT — SEVERITY RUNBOOK {rb} (WITH FLOORS) AND POST-INCIDENT REVIEW PACK", core, ctx, "REVIEW PACK", case)
    instr = pick([f"What final severity must the post-incident review assign under {rb}? Output the level index (0 = SEV-4 ... 3 = SEV-1).", f"Apply {rb} in full — base severity, floors, adjustments in order — and select the final severity level index.",
                  f"Determine the final severity of the incident in the review pack under {rb}."])
    return score(state, instr, ['Severity 4 — the lowest level', 'Severity 3', 'Severity 2', 'Severity 1 — the highest level'], sev)

