def near_miss_options(cur, truth, wrongs, k=5):
    """Option dict of k amounts: the truth plus distinct wrong-method values, padded with plausible perturbations."""
    vals = [r2(truth)]
    for w in wrongs:
        w = r2(w)
        if all(abs(w - v) > 0.005 for v in vals): vals.append(w)
    while len(vals) < k:
        w = r2(truth * rr(0.9, 1.1) + rr(-9, 9))
        if all(abs(w - v) > 0.5 for v in vals) and w > 0: vals.append(w)
    vals = vals[:k]
    return {amt_key(v, cur): f"{pick(['Amount', 'Result', 'Figure'])} {cur} {v:,.2f}." for v in vals}, amt_key(truth, cur)

def tn_warranty():
    co = pick(COMPANIES); fmt = pick(DATE_FMTS); hq = pick(['Rotterdam', 'Lyon', 'Dublin', 'Gdańsk']); hq_off = pick([0, 1, 2])
    cust = pick(CITIES); c_off = CITY_OFF[cust]; months = pick([12, 18, 24, 36]); delivery = pick([D(2026, 8, 31), D(2026, 5, 31), D(2025, 8, 29), D(2026, 10, 31), D(2026, 3, 30), rand_date(2025, 9, 2026, 12)])
    end, clamped = add_months(delivery, months); end_utc = DT.combine(end + TD(days=1), datetime.time(0, 0)) - TD(hours=hq_off)
    claim_utc = end_utc + TD(hours=rr(-30, 30)); claim_local = claim_utc + TD(hours=c_off); claim_local = claim_local.replace(minute=pick([0, 15, 30, 45]), second=0, microsecond=0)
    claim_utc = claim_local - TD(hours=c_off); within = claim_utc < end_utc; prod = pick(['fridge-freezer', 'heat pump', 'washer-dryer', 'e-bike'])
    naive_end = (add_months(delivery, months)[0] - TD(days=1)) if clamped else end
    st = para(f"{co.upper()} — EXTENDED WARRANTY CERTIFICATE {ref('EW', 6)} (EXTRACT) AND CLAIM RECORD", '', f"Product: {prod}, serial {rint(1000, 9999)}-{rint(10000, 99999)}. Delivery date: {fmt(delivery)}.",
              f"Term: cover runs from the delivery date and ends {months} months later. If the month in which the period would end has no day with the same number as the delivery day, the period ends on the last day of that month. The period ends at 24:00 on its last day.",
              f"Time reference: all times are read in {co}'s local time at its claims centre in {hq} ({utc_s(hq_off)} on the dates concerned). Online claims are time-stamped in the customer's local time and must be converted.",
              "A claim is \"reported\" when the online form is submitted or a call to the claims line begins.", '', f"Claim record {ref('CL', 5)}", f"Customer location: {cust}; customer's local zone on the submission date: {utc_s(c_off)}.",
              f"Online claim form submitted: {fmt(claim_local.date())} at {claim_local.strftime('%H:%M')} customer local time.", f"Fault: {pick(['compressor does not start', 'unit trips the breaker', 'controller shows error E4'])}.",
              note('draft', f"{months} months from {fmt(delivery)} is {fmt(naive_end)}; the claim came in {'after' if claim_local.date() > naive_end else 'on or before'} that day{', so recommend decline' if claim_local.date() > naive_end else ''}."))
    instr = pick(["Was the claim reported within the extended warranty period of the certificate?", "Under the certificate's term and time-reference clauses, did the claim arrive before cover ended?", "Does the claim fall inside the warranty period once the end date and the time zones are applied?"])
    return noul(st, instr, f"Reported before cover ended, measured in {hq} local time.", "Reported only after the warranty period had already ended.", within)

def tn_budget_alert():
    co = pick(COMPANIES); month = pick([(2026, 9), (2026, 11), (2027, 2), (2027, 4)]); ndays = calendar.monthrange(*month)[1]; budget = pick([8000, 12000, 15000, 20000]); pct = pick([70, 80, 90])
    daily = budget / ndays * rr(0.85, 1.05); rows = []; credit_day = rint(8, 18); credit = round(daily * rr(1.2, 2.5) / 10) * 10; tax = pick([7, 8, 10, 19])
    for d in range(1, ndays + 1):
        u = r2(daily * rr(0.85, 1.15)); rows.append([d, u, credit if d == credit_day else 0.0, r2(u * tax / 100)])
    def first_day(with_tax, with_credit):
        cum = 0
        for d, u, c, t in rows:
            cum += u + (t if with_tax else 0) - (c if with_credit else 0)
            if cum >= budget * pct / 100: return d
        return None
    truth = first_day(False, True); naive = first_day(True, False)
    if truth is None: return None
    days = sorted(set([truth] + [truth + k for k in (-2, -1, 1, 2)] + ([naive] if naive else []))); days = [d for d in days if 1 <= d <= ndays]
    while len(days) > 5:
        rem = [d for d in days if d != truth and d != naive]
        if not rem: break
        days.remove(pick(rem))
    mon = MONTHS[month[1] - 1]; fmt_row = lambda d, u, c, t: f"{mon[:3]} {d:02d} | usage {u:,.2f} | credits {c:,.2f} | tax ({tax}%) {t:,.2f}"
    st = para(f"{co.upper()} CLOUD — BUDGET ALERT CONFIGURATION AND DAILY COST EXPORT ({mon.upper()} {month[0]}, USD)", '', f"Monthly budget: USD {budget:,.2f}.",
              f"Alert rule B1: fires once, at the end of the first day on which month-to-date net cost is at or above {pct}% of the monthly budget.",
              "Net cost = usage charges minus credits applied, excluding tax. Tax is informational and never counts toward budgets. A credit counts on the day it is applied.",
              f"A {pick(['migration', 'promotional', 'support'])} credit of USD {credit:,.2f} was applied on {mon} {credit_day}.", '', 'Daily export:', *[fmt_row(*r) for r in rows], '',
              note('chat', f"With tax we crossed {budget * pct / 100:,.0f} on {mon} {naive} — why hasn't B1 fired?") if naive and naive != truth else note('chat', 'Someone check when B1 is supposed to go off.'))
    opts = {f"{mon[:3].lower()}_{d:02d}": f"B1 fires at the close of {d} {mon}." for d in days}
    instr = pick(["On which day does alert rule B1 fire?", "Determine the day at whose end alert B1 fires under its definition.", "Which day's end triggers B1?"])
    return choice(st, instr, opts, f"{mon[:3].lower()}_{truth:02d}", bal='fire')

def tn_dose():
    a, b = sample(CITIES, 2); oa, ob = CITY_OFF[a], CITY_OFF[b]; lo, hi = pick([(11, 13), (10, 14), (7, 9), (23, 25)]); target = (lo + hi) / 2
    t1 = DT(2026, pick([5, 6, 9]), rint(2, 26), rint(6, 14), pick([0, 30])); t1_utc = t1 - TD(hours=oa)
    elapsed = pick([rr(lo, hi), rr(lo - 6, lo - 0.5), rr(hi + 0.5, hi + 6)]); elapsed = round(elapsed * 2) / 2
    t2_utc = t1_utc + TD(hours=elapsed); t2 = t2_utc + TD(hours=ob); truth = lo <= elapsed <= hi
    clock_diff = (t2 - t1).total_seconds() / 3600; drug = pick(['Immunovex', 'Cardiline', 'Neurotral']); fmt = pick(DATE_FMTS)
    st = para(f"PATIENT MEDICATION GUIDANCE — {drug.upper()} (FICTIONAL), DOSING EVERY {int(target)} HOURS — EXTRACT, AND TRAVEL DIARY", '',
              f"Dosing rule: a dose is \"on schedule\" if taken no earlier than {lo} hours and no later than {hi} hours after the previous dose, measured in actual elapsed time. When crossing time zones, do not follow the destination clock; compute elapsed time.",
              f"Time zones on the travel dates: {a} {utc_s(oa)}; {b} {utc_s(ob)}.", '', 'Travel diary:', f"- {fmt(t1.date())}, {t1.strftime('%H:%M')} {a} time: took dose at home.",
              f"- flight departed {a} at {(t1 + TD(hours=rr(1.5, 4))).strftime('%H:%M')} {a} time; watch set to {b} time on boarding.",
              f"- {fmt(t2.date())}, {t2.strftime('%H:%M')} by my watch ({b} time): took the next dose. \"" + (f"That's {clock_diff:g} hours after the last one by the clock — {'fine' if lo <= clock_diff <= hi else 'a bit off'}." if clock_diff > 0 else "The clock went backwards on me with the zone change, so I just took it when the meal came.") + '"',
              f"- landed {b} {(t2 + TD(hours=rr(1, 5))).strftime('%H:%M')} {b} time.", "Clinic sheet: keep a written log of dose times in one time zone while travelling.")
    instr = pick([f"Was the dose taken at {t2.strftime('%H:%M')} {b} time on schedule according to the dosing rule?", "Under the dosing rule, was the in-flight dose on schedule?", "Apply the elapsed-time rule: was the second dose taken within the permitted window?"])
    return noul(st, instr, f"Taken between {lo} and {hi} hours (inclusive) of real elapsed time after the previous dose.", f"Taken less than {lo} or more than {hi} hours of real elapsed time after the previous dose.", truth)

def dst_change():
    """Return (date, kind, off_before, off_after, zone_name) for a DST transition used in roster problems."""
    return pick([(D(2026, 10, 25), 'back', 2, 1, 'CEST/CET'), (D(2027, 3, 28), 'forward', 1, 2, 'CET/CEST'), (D(2026, 11, 1), 'back', -4, -5, 'EDT/EST'), (D(2027, 3, 14), 'forward', -5, -4, 'EST/EDT'), (D(2026, 10, 25), 'back', 1, 0, 'BST/GMT')])
def local_to_utc_min(day, minute, change, kind, off_b, off_a):
    """day: date; minute: minutes past local midnight (may exceed 1440). Transition at 03:00 (back -> 02:00) or 02:00 (forward -> 03:00) local on `change`."""
    t = DT.combine(day, datetime.time(0, 0)) + TD(minutes=minute); trans = DT.combine(change, datetime.time(3 if kind == 'back' else 2, 0))
    off = off_b if t < trans else off_a
    return t - TD(hours=off)
def tn_rest_violations():
    change, kind, ob, oa, zn = dst_change(); start = change - TD(days=rint(2, 4)); shifts = []; day = start; cur = rint(6 * 60, 14 * 60)
    for i in range(rint(7, 9)):
        length = pick([8, 8, 9, 10, 12]) * 60; s = cur; e = s + length; shifts.append((day, s, e)); gap = pick([600, 630, 660, 660, 690, 720, 900, 1200]); cur = e + gap
        while cur >= 1440: cur -= 1440; day += TD(days=1)
    rests_actual, rests_clock = [], []
    for (d1, s1, e1), (d2, s2, e2) in zip(shifts, shifts[1:]):
        u1 = local_to_utc_min(d1, e1, change, kind, ob, oa); u2 = local_to_utc_min(d2, s2, change, kind, ob, oa)
        rests_actual.append((u2 - u1).total_seconds() / 3600); rests_clock.append(((DT.combine(d2, datetime.time(0)) + TD(minutes=s2)) - (DT.combine(d1, datetime.time(0)) + TD(minutes=e1))).total_seconds() / 3600)
    viol = sum(1 for r in rests_actual if r < 11 - 1e-9); viol_clock = sum(1 for r in rests_clock if r < 11 - 1e-9); lvl = min(viol, 3)
    lines = [f"S{i + 1} {d.strftime('%a %d %b')} {hm(s)} – {(('' if e < 1440 else (d + TD(days=1)).strftime('%a %d %b ')) + hm(e))}" for i, (d, s, e) in enumerate(shifts)]
    st = para(f"{pick(['REGIONAL AMBULANCE SERVICE', 'PORT AUTHORITY OPERATIONS', 'RAIL CONTROL CENTRE'])} — WORKING TIME RULE WT-{rint(2, 9)} AND ROSTER EXTRACT ({person().upper()})", '',
              "Daily rest: between the end of one shift and the start of the next there must be at least 11 consecutive hours of rest, measured in actual elapsed time. Exactly 11 hours complies. Each rest shorter than 11 hours is one violation.",
              f"Clock change: on {wd(change)} {d_long(change)} at {'03:00 local summer time clocks go back to 02:00' if kind == 'back' else '02:00 local standard time clocks go forward to 03:00'} ({zn}, {utc_s(ob)} before, {utc_s(oa)} after). The roster shows local wall-clock times only.",
              '', 'Roster (local times):', *lines, '', "Rest periods are measured from the rostered end of one shift to the rostered start of the next.",
              note('chat', f"By the roster clock I count {viol_clock} problem rest{'s' if viol_clock != 1 else ''}.") if viol_clock != viol else note('lead', 'Remember to apply the clock change to the rests around the weekend.'))
    instr = pick(["How many daily-rest violations does this roster contain? (0 = none, 1 = one, 2 = two, 3 = three or more.)", "Count the rest periods shorter than 11 hours of actual elapsed time and output the level index (3 means three or more).", "Under the daily-rest rule, how many violations are in the roster extract?"])
    return score(st, instr, ['No rest violations', 'One rest violation', 'Two rest violations', 'Three or more rest violations'], lvl)

def tn_weekly():
    change, kind, ob, oa, zn = dst_change(); home_off = pick([-4, -5, 8, 10]); home = {-4: 'New York', -5: 'Chicago', 8: 'Singapore', 10: 'Sydney'}[home_off]; cov = {'CEST/CET': 'Berlin', 'CET/CEST': 'Berlin', 'EDT/EST': 'Toronto', 'EST/EDT': 'Toronto', 'BST/GMT': 'London'}[zn]
    monday = change - TD(days=change.weekday()); shifts = []; total_target = pick([44, 46, 47, 48, 48, 49, 50])
    plan = [(monday + TD(days=i), 'home', 8 * 60, 8 * 60 + pick([6, 7, 8]) * 60) for i in range(4)]
    plan.append((monday + TD(days=4), 'home', 23 * 60, 23 * 60 + pick([8, 9]) * 60))
    cov_start = pick([60, 120]); plan.append((change, 'cov', cov_start, cov_start + pick([9, 10]) * 60))
    def utc(day, m, which):
        return local_to_utc_min(day, m, change, kind, ob, oa) if which == 'cov' else DT.combine(day, datetime.time(0)) + TD(minutes=m) - TD(hours=home_off)
