def tn_card():
    co = pick(COMPANIES); limit = pick([5000, 6000, 8000]); month = (2026, pick([9, 10, 11])); ndays = calendar.monthrange(*month)[1]; fee = 3
    events = []; day = 1; purchases = []
    for i in range(rint(9, 12)):
        day += rint(1, 3)
        if day > ndays - 1: break
        kind = R.choices(['purchase', 'preauth', 'refund'], [7, 2, 1])[0]
        if kind == 'purchase':
            foreign = chance(.3); amt = r2(pick([rr(15, 60), rr(100, 700), rr(900, 1600)])); events.append(dict(day=day, kind='purchase', amt=amt, foreign=foreign, desc=f"{pick(['airline ticket', 'hotel', 'software licence', 'office chair', 'taxi', 'parking', 'book set', 'client dinner', 'conference fee'])}{' (' + pick(['GB', 'AT', 'JP', 'FR']) + ')' if foreign else ' (US)'}"))
        elif kind == 'preauth':
            amt = r2(rr(400, 1000)); events.append(dict(day=day, kind='preauth', amt=amt, foreign=False, desc=pick(['hotel pre-authorisation', 'car rental pre-authorisation'])))
            if chance(.6): events.append(dict(day=min(day + rint(2, 5), ndays), kind='settle', amt=r2(amt * rr(0.6, 1.1)), foreign=False, desc=f"settlement of the {MONTHS[month[1] - 1][:3]} {day:02d} pre-authorisation", ref=len(events) - 1))
        else:
            prev = [e for e in events if e['kind'] == 'purchase']
            if prev: p = pick(prev); full = chance(.5); events.append(dict(day=day, kind='refund', amt=p['amt'] if full else r2(p['amt'] * rr(0.2, 0.6)), foreign=False, desc=('full refund' if full else 'partial refund') + f" of the {p['desc']}", full=full))
    events.sort(key=lambda e: (e['day'], e['kind'] != 'preauth'))
    avail = limit; open_auth = {}; first_declined = None; lines = []
    for i, e in enumerate(events):
        for j in [j for j, (d, a) in open_auth.items() if e['day'] >= d + 8]: avail += open_auth.pop(j)[1]
        if e['kind'] == 'purchase':
            charge = r2(e['amt'] * (1 + fee / 100) if e['foreign'] else e['amt']); ok = charge <= avail + 1e-9
            if ok: avail -= charge
            elif first_declined is None: first_declined = i
            lines.append(f"{MONTHS[month[1] - 1][:3]} {e['day']:02d}  {e['desc']:38s} purchase  {e['amt']:,.2f} USD" + (' equivalent (charged in foreign currency)' if e['foreign'] else '')); e['ok'] = ok
        elif e['kind'] == 'preauth': open_auth[i] = (e['day'], e['amt']); avail -= e['amt']; lines.append(f"{MONTHS[month[1] - 1][:3]} {e['day']:02d}  {e['desc']:38s} pre-authorisation  {e['amt']:,.2f} USD")
        elif e['kind'] == 'settle':
            if e['ref'] in open_auth: avail += open_auth.pop(e['ref'])[1]
            avail -= e['amt']
            lines.append(f"{MONTHS[month[1] - 1][:3]} {e['day']:02d}  {e['desc']:38s} settlement  {e['amt']:,.2f} USD")
        else:
            if e['full']: avail += e['amt']
            lines.append(f"{MONTHS[month[1] - 1][:3]} {e['day']:02d}  {e['desc']:38s} refund  {e['amt']:,.2f} USD")
    purchases = [(i, e) for i, e in enumerate(events) if e['kind'] == 'purchase']
    if len(purchases) < 4: return None
    if first_declined is None: cand = purchases[-4:]
    else:
        idx = sorted({first_declined} | set(p[0] for p in sample(purchases, min(4, len(purchases)))))[:5]
        if first_declined not in idx: idx = idx[:4] + [first_declined]
        cand = [(i, events[i]) for i in sorted(idx)]
    opts = {'none_declined': 'Every listed purchase was approved; nothing was declined.'}; keyof = {}
    for i, e in sorted(cand, key=lambda p: p[0]):
        k = f"{MONTHS[month[1] - 1][:3].lower()}_{e['day']:02d}_{e['desc'].split(' (')[0].replace(' ', '_')}"; keyof[i] = k; opts[k] = f"The {e['day']} {MONTHS[month[1] - 1][:3]} {e['desc'].split(' (')[0]} (USD {e['amt']:,.2f}) is the first declined purchase."
    truth = 'none_declined' if first_declined is None else keyof[first_declined]
    st = para(f"{co.upper()} — CORPORATE CARD DESK", f"Query from cardholder {person()} (card ending {rint(1000, 9999)}): \"Which of my purchases got declined this cycle? I deleted the text.\"", '',
              'Card programme rules (schedule B)', f"B1 Cycle limit: USD {limit:,.2f} per statement cycle; the cycle runs 1–{ndays} {MONTHS[month[1] - 1]} {month[0]}.",
              "B2 A purchase is approved only if the amount it would charge, including any fee charged with it, is not more than the available limit at that moment. A declined purchase has no effect on the limit.",
              "B3 Available limit = cycle limit − settled purchases and fees − open pre-authorisations + restored amounts.", "B4 A pre-authorisation is held as an open authorisation; when the merchant settles, the settled amount replaces it. An unsettled authorisation is released at 00:00 on the 8th calendar day after the day of authorisation.",
              f"B5 Foreign transaction fee: {fee}% of the USD amount of any purchase from a merchant outside the United States, charged with the purchase.", "B6 A full refund restores the amount to the available limit on its posting date. A partial refund is credited to the statement but does not restore available limit within the cycle.", '',
              'Card activity, in order (no two events on the same day at the same moment; pre-authorisations precede other events of their day):', *lines)
    instr = pick(["Under schedule B, which listed purchase was the first one declined?", "Apply B1–B6 to the activity list: which purchase was declined first (or none)?", "Which of the listed purchases is the first that the limit rules decline?"])
    return choice(st, instr, opts, truth, bal='none' if first_declined is None else 'declined')

