              f"Nightly caps (EUR): {city} {cap}; {pick(['Kyoto', 'Busan', 'Geneva', 'Bergen'])} {cap - 20}.", '', f"Treasury reference rates (EUR 1 = {ccy[0]}), published on business days:", *[f"{wd(k)[:3]} {d_long(k)}  {v:,.2f}" for k, v in sorted(rates.items())], '',
              f"Hotel folio (all amounts {ccy[0]}; folio closed and card charged at check-out on {d_long(depart)})", *folio, '', f"Card statement: posted {d_long(depart + TD(days=2))}, {ccy[0]} {sum(room) + tax * nights + bf * (nights - 1):,} = EUR {(sum(room) + tax * nights + bf * (nights - 1)) / card_rate:,.2f} (card issuer rate).",
