SERVICES = [('rate-limiter', ['rld', 'rl-sidecar']), ('payments-router', ['payrt']), ('kyc-service', ['kycd']), ('invoice-gen', ['invgen']), ('search-api', ['srch', 'srch-index']), ('session-cache', ['sesscache']),
            ('email-relay', ['mailrly']), ('fraud-rules', ['frules', 'rules-py']), ('ledger-writer', ['ledgw', 'ledg-migrator']), ('report-builder', ['rptb']), ('feature-flags', ['flagd']), ('audit-log', ['auditd']),
            ('webhook-out', ['hookout']), ('settlement-batch', ['settlb']), ('card-vault', ['vaultd']), ('fx-quotes', ['fxq'])]
TEAMS = ['Edge', 'Identity', 'Money-Flow', 'Core-Ledger', 'Risk', 'Data-Finance', 'Messaging', 'Storefront', 'Discovery', 'Platform']
RULES = ['PodRestartStorm', 'ErrorBudgetBurn', 'DiskNearlyFull', 'CertificateExpiring', 'ReplicaLagHigh', 'QueueDepthHigh']
def mh_oncall():
    co = pick(COMPANIES); tz_off = pick([2, 1, -4, 5.5]); tz_name = {2: 'Europe/Berlin (CEST, UTC+2)', 1: 'Europe/Lisbon (WEST, UTC+1)', -4: 'America/Toronto (EDT, UTC-4)', 5.5: 'Asia/Kolkata (IST, UTC+5:30)'}[tz_off]
    teams = sample(TEAMS, 6); merged_from, merged_into = teams[0], teams[1]; svcs = sample(SERVICES, rint(10, 14))
    catalog = [(s, procs, pick(teams[:5]), pick(['tier-1', 'tier-2', 'tier-3'])) for s, procs in svcs]
    base = {r: pick(['SEV2', 'SEV3']) for r in RULES}; adj = {}
    for r in RULES:
        b = int(base[r][-1]); adj[r] = {'tier-1': f"SEV{max(1, b - 1)}", 'tier-2': f"SEV{b}", 'tier-3': f"SEV{min(4, b + 1)}"}
    people = sample(FIRST, 8); rot_people = people[:4]; old_people = people[4:6]
    alert_utc = DT(2026, pick([9, 10]), rint(8, 27), rint(0, 23), rint(0, 59)); alert_local = alert_utc + TD(hours=tz_off)
    handover_wd = rint(0, 4); handover_h = pick([9, 10, 8]); weeks = []
    first = alert_local.date() - TD(days=14); first -= TD(days=(first.weekday() - handover_wd) % 7)
    for i in range(4):
        ws = DT.combine(first + TD(days=7 * i), datetime.time(handover_h)); weeks.append((ws, ws + TD(days=7), rot_people[i % 4], rot_people[(i + 1) % 4]))
    old_weeks = [(ws, we, old_people[i % 2], old_people[(i + 1) % 2]) for i, (ws, we, _, _) in enumerate(weeks[-2:])]
    overrides = []
    for _ in range(rint(2, 4)):
        wk = pick(weeks); s = wk[0] + TD(hours=rint(0, 150)); e = s + TD(hours=rint(4, 16)); overrides.append((s, e, wk[2], pick([p for p in people[:6] if p != wk[2]]), pick(['dentist', 'travel', 'family event', 'swap'])))
    if chance(.5):  # override that brackets the alert closely
        s = alert_local - TD(hours=rint(1, 12)); e = alert_local + TD(minutes=pick([-30, -5, 0, 5, 45, 180])); wk = [w for w in weeks if w[0] <= alert_local < w[1]][0]
        overrides.append((s, e, wk[2], pick([p for p in people[:6] if p != wk[2]]), 'cover'))
    overrides.sort()
    target = pick(catalog); rule = pick(RULES); proc = pick(target[1]); team = target[2]; team_eff = merged_into if team == merged_from else team
    sev = adj[rule][target[3]]; pages = sev in ('SEV1', 'SEV2')
    if pages and team_eff != merged_into: return None  # only the merged rotation is listed; a page to another team has no listed answer
    if not pages: truth = 'no_page_ticket_only'
    else:
        wk = [w for w in weeks if w[0] <= alert_local < w[1]]
        if not wk: return None
        primary = wk[0][2]
        for s, e, sched, rep, _ in overrides:
            if s <= alert_local < e and sched == primary: primary = rep
        truth = primary
    if truth is None: return None
    matrix = md_table(['Alert rule', 'Base', 'tier-1', 'tier-2', 'tier-3'], [[r, base[r], adj[r]['tier-1'], adj[r]['tier-2'], adj[r]['tier-3']] for r in RULES])
    cat = md_table(['Service', 'Process names', 'Owning team', 'Tier'], [[s, ', '.join(p), t, tier] for s, p, t, tier in sorted(catalog)])
    rot = md_table(['Week (from handover to next handover)', 'Primary', 'Secondary'], [[f"{ws.strftime('%Y-%m-%d %H:%M')} → {we.strftime('%Y-%m-%d %H:%M')}", p, s] for ws, we, p, s in weeks])
    old = md_table(['Week', 'Primary', 'Secondary'], [[f"{ws.strftime('%Y-%m-%d')} → {we.strftime('%Y-%m-%d')}", p, s] for ws, we, p, s in old_weeks])
    ov = md_table(['Rotation', 'Start', 'End', 'Scheduled primary', 'Replaced by', 'Reason'], [[f"{merged_into.lower()}-primary", s.strftime('%Y-%m-%d %H:%M'), e.strftime('%Y-%m-%d %H:%M'), a, b, r] for s, e, a, b, r in overrides])
    naive_team = merged_from if team == merged_from else team; naive_person = old_weeks[-1][2] if team == merged_from else pick(people)
    st = para(f"{co.upper()} — ON-CALL ROUTING HANDBOOK (SRE), version {rint(9, 20)}", '', '1. HOW AN ALERT BECOMES A PAGE',
              "1.1 Alerts name the failing PROCESS and host, not the service. Map the process to its service with the catalog (section 3); a service may run several processes.", "1.2 The rule's base severity is adjusted by the service tier (section 2). Only SEV1 and SEV2 page a human; SEV3 and SEV4 create a ticket and page nobody, at any hour.",
              "1.3 The page goes to the PRIMARY on-call of the team that owns the service, after checking the team directory (section 4) for merges: if a team's services were transferred, page the receiving team's rotation.",
              f"1.4 Rotation and override times are in {tz_name}. Alert timestamps are UTC.", "1.5 An override replaces the scheduled primary for the window [start, end) — an alert exactly at the end time is not covered by the override.", "1.6 Never page a secondary directly.", '',
              '2. SEVERITY MATRIX', matrix, '', '3. SERVICE CATALOG', cat, '', '4. TEAM DIRECTORY',
              f"- {merged_from} — MERGED into {merged_into} effective {(alert_local - TD(days=rint(10, 40))).strftime('%Y-%m-%d')} 00:00 local. Its services are covered by the {merged_into.lower()}-primary rotation; the {merged_from.lower()}-primary rotation is retired and kept read-only for audit — do not page it.",
              f"- {merged_into} — rotation {merged_into.lower()}-primary (covers former {merged_from} services from the merge date).", *[f"- {t} — rotation {t.lower()}-primary (weekly)." for t in teams[2:5]], f"- {teams[5]} — business hours only, tickets only.", '',
              f"5. ROTATION SCHEDULES — {merged_into.lower()}-primary, weekly, handover every {calendar.day_name[handover_wd].upper()} {handover_h:02d}:00 local", rot, '', f"{merged_from.lower()}-primary (RETIRED, read-only)", old, '', '6. OVERRIDES (local time)', ov, '',
              '7. ALERT TO ROUTE', f"Alertmanager, {alert_utc.strftime('%Y-%m-%dT%H:%M')}Z", f"  rule: {rule}", f"  labels: process=\"{proc}\", host=\"{pick(['pay-eu-3', 'core-7', 'edge-12'])}\", env=\"prod\"",
              note('chat', f"{proc}... that's {naive_team}, right? {naive_person} is on their sheet this week."))
    opts = {p.lower(): f"Page {p} as primary." for p in people[:5] + ([truth] if truth != 'no_page_ticket_only' and truth not in people[:5] else [])}; opts['no_page_ticket_only'] = 'Nobody is paged; the alert only opens a ticket.'
    instr = pick(["Per the handbook, which primary must be paged for this alert, if anyone?", "Route the alert in section 7 under the handbook: which primary is paged, if any?", "Apply sections 1–6 to the alert: who receives the page?"])
    return choice(st, instr, opts, truth.lower() if truth != 'no_page_ticket_only' else truth, bal='nopage' if truth == 'no_page_ticket_only' else 'page')

def mh_bursary():
    co = pick(COMPANIES).split()[0] + ' ' + pick(['Community College', 'Polytechnic', 'Institute']); fmt = pick(DATE_FMTS); ref_date = D(2026, 9, 1); levels = [0, 500, 1200, 2000, 3000]
    thr = pick([(7000, 10500, 14000, 18000), (6500, 9800, 13200, 17000), (8000, 12000, 16000, 20000)]); cap_assets = pick([30000, 40000]); age = rint(19, 27)
    dob = D(ref_date.year - age, rint(1, 12), rint(1, 28)); age_on = ref_date.year - dob.year - ((ref_date.month, ref_date.day) < (dob.month, dob.day))
    status = pick(['single', 'married', 'civil_partnership', 'cohabiting']); child = chance(.2); care = chance(.1)
    independent = age_on >= 24 or status in ('married', 'civil_partnership') or child or care
    own_job = round(rr(3000, 12000) / 100) * 100; work_study = round(rr(1500, 4000) / 100) * 100 if chance(.7) else 0; gift = pick([0, 400, 800, 1500]); partner_inc = round(rr(14000, 32000) / 100) * 100
    p1 = round(rr(20000, 70000) / 1000) * 1000; p2 = round(rr(0, 30000) / 1000) * 1000; sib_uni = rint(0, 2); sib_minor = rint(0, 2); child_benefit = 3000 if sib_minor else 0
    savings = pick([4000, 9400, 22000, 45000, 61000])
    if independent:
        hh = 1 + (1 if status in ('married', 'civil_partnership') else 0) + (1 if child else 0); countable = own_job + (partner_inc if status in ('married', 'civil_partnership') else 0) + (gift if gift >= 1000 else 0)
    else:
        hh = 2 + (1 if p2 else 0) + sib_uni + sib_minor; countable = p1 + p2 + own_job + (gift if gift >= 1000 else 0) - 2000 * sib_uni
    per_capita = round(countable / hh); lvl = 4 - sum(per_capita > t for t in thr)
    if savings > cap_assets: lvl = min(lvl, 1)
    naive_ind = age_on >= 24 or child; naive_hh = 2 + (1 if p2 else 0) + sib_uni + sib_minor; naive_pc = round((p1 + p2 - 2000 * sib_uni) / naive_hh); naive_lvl = 4 - sum(naive_pc > t for t in thr)
    if not independent: naive_pc = round((p1 + p2 + own_job + work_study) / naive_hh); naive_lvl = 4 - sum(naive_pc > t for t in thr)
    civ = {'single': 'single', 'married': 'married (certificate on file)', 'civil_partnership': 'registered civil partnership (certificate on file)', 'cohabiting': 'living with partner, not married or registered'}[status]
    st = para(f"{co.upper()} — HARDSHIP BURSARY REGULATIONS {ref_date.year}/{ref_date.year + 1 - 2000}", f"(Approved by the Student Finance Committee. Awards for the academic year starting {fmt(ref_date)}.)", '',
              'PART A — AWARD LEVELS', *[f"    Level {i} — {'no award' if not v else f'EUR {v:,}'}" for i, v in enumerate(levels)], "A.2 The level follows the PER-CAPITA COUNTABLE INCOME of the assessed household (Part D) via the table in Part E, subject to the asset rule in Part F.", '',
              'PART B — DEPENDENCY STATUS', f"B.1 A student is INDEPENDENT if on the reference date ({fmt(ref_date)}) at least one holds: (a) aged 24 or older; (b) married; (c) has a dependent child living with them; (d) was in local-authority care after age 16.", "B.2 Otherwise the student is DEPENDENT.",
              "B.3 A registered civil partnership is treated exactly like a marriage for every purpose of these regulations. Cohabitation without marriage or civil partnership does not make a student independent.", '',
              'PART C — ASSESSED HOUSEHOLD', "C.1 Dependent students: the parent(s) the student normally lives with, their spouse or partner, the student, and all other children living in that household.", "C.2 Independent students: the student, their spouse (if any) and their dependent children (if any). Parental income is NOT assessed for independent students even if supplied on the form.", "C.3 Household size = number of persons in the assessed household.", '',
              'PART D — COUNTABLE INCOME', f"D.1 Countable income = sum over the assessed household (excluding children under 18) of gross employment income for {ref_date.year - 1}, net self-employment profit, pensions and taxable benefits.",
              "D.2 Excluded: child benefit; disability allowances; student loans and grants; earnings from the college's WORK-STUDY programme (for any student); one-off gifts under EUR 1,000.", "D.3 Dependent students only: deduct EUR 2,000 for each OTHER child of the household enrolled full-time in higher education.", "D.4 Per-capita countable income = countable income ÷ household size, rounded to the nearest euro.", '',
              'PART E — LEVEL TABLE (per-capita countable income, EUR)', md_table(['Per-capita countable income', 'Level'], [[f"up to {thr[0]:,}", 4], [f"{thr[0] + 1:,} – {thr[1]:,}", 3], [f"{thr[1] + 1:,} – {thr[2]:,}", 2], [f"{thr[2] + 1:,} – {thr[3]:,}", 1], [f"above {thr[3]:,}", 0]]), '',
              'PART F — ASSETS', f"F.1 If the assessed household's savings and investments (excluding the main home and one car) exceed EUR {cap_assets:,}, the level is capped at Level 1.", '',
              'PART G — FAQ', "Q: I filled in my parents' details because the form asked. Does that matter? — A: The form collects parental data from everyone; whether it is used depends only on Part B.", "Q: My work-study job is my main income. — A: Still excluded (D.2).", "Q: Can I deduct my sibling at university? — A: Only dependent students' households get D.3.", '',
              '=' * 60, f"APPLICATION {ref('HB', 4)} — received {fmt(ref_date + TD(days=rint(3, 30)))}", '=' * 60,
              f"Student: {person()}, {pick(['AS Laboratory Technology', 'BSc Nursing', 'Diploma in Logistics'])}, full-time. Date of birth: {fmt(dob)}.",
              f"Civil status: {civ}.", f"Dependent children: {'one child aged ' + str(rint(1, 6)) + ' living with the student' if child else 'none'}. Local-authority care history: {'yes, aged 16–18' if care else 'none'}.",
              f"Section 2 — student's and partner's income, calendar year {ref_date.year - 1}:", md_table(['Person', 'Source', 'Amount EUR'], [['Student', 'Part-time employment (gross)', f"{own_job:,}"], ['Student', 'College work-study programme', f"{work_study:,}"], ['Student', 'Gift from a relative', f"{gift:,}"], ['Partner', 'Employment (gross)', f"{partner_inc:,}"]][: (4 if status != 'single' else 3)]),
              f"Section 3 — parents' household (completed by applicant): parent 1 employment EUR {p1:,}; parent 2 employment EUR {p2:,}{'; child benefit received EUR ' + f'{child_benefit:,}' if child_benefit else ''}. Other children in the parents' household: {sib_uni} full-time university student(s), {sib_minor} under 18.",
              f"Section 4 — assets: {'student and partner joint savings' if status != 'single' else 'student savings'} EUR {savings:,}; one car.",
              note('draft', f"Student is {age_on} on the reference date → {'independent' if naive_ind else 'dependent'}. {'Use parents: ' if not naive_ind else 'Own household: '}per capita about {naive_pc:,} → Level {naive_lvl}."))
    instr = pick(["Apply the bursary regulations to the application. What award level (0–4) should the student receive?", "Determine the student's award level under Parts B–F; output the level index.", "Assess the application under the regulations and select the award level."])
    return score(st, instr, [f"Level {i}: {'no award' if not v else 'award of EUR ' + f'{v:,}'}" for i, v in enumerate(levels)], lvl)

ARCHIVE_KINDS = [('governance note', 'The live handbook ranks signed registries and dated case evidence above summaries, posters and drafts; this note orders sources and decides nothing by itself.'),
                 ('superseded revision', 'An earlier revision {v} treated {topic} differently; it carries an effective-end date and a superseded watermark and is kept for audit comparison only.'),
                 ('same-alias history', 'A previous case using the alias {alias} reached a different result on different facts; historical values are not reusable without matching identifier, date and scope.'),
                 ('training example', 'A training exercise built on {alias} changes one material fact and is marked illustrative, not precedent.'),
                 ('migration receipt', 'A migration checksum confirms live entries for {alias} were copied intact; the receipt interprets nothing.'),
                 ('clerical ticket', 'A clerk flagged inconsistent capitalisation of {topic}; the data owner marked it display-only because normalised identifiers already match.'),
                 ('closed exception', 'A one-time exception expired with its named case and expressly creates no standing waiver.'),
                 ('committee minutes', 'Minutes record a deferred proposal to simplify rules around {alias}; minutes do not supersede signed material.'),
                 ('vendor bulletin', 'An external bulletin recommends a more permissive reading of {topic}; the organisation did not adopt it.'),
                 ('retention marker', 'This archive segment is retained until 2031 for reproducibility; retention keeps a record readable, not operative.'),
                 ('dashboard cache alert', 'A dashboard cached an older description of {topic}; operators were directed to the dated registry, which was not changed.')]
def archive_block(prefix, alias, topic, v):
    recs = []
    for i, (kind, text) in enumerate(sample(ARCHIVE_KINDS, rint(5, 9)), 1):
        recs.append({'record': f"{prefix}-{rint(10, 99)}-{i:02d}", 'kind': kind, 'status': pick(['archived', 'reference']), 'effective_scope': 'background only',
                     'detail': text.format(alias=alias, topic=topic, v=v), 'reader_note': pick(['Check scope and authority before relying on this record; only explicitly current material outside the archive governs.', 'Matching keywords and a retained status do not make a historical fact operative.', 'Verify effective date and exact identifier before importing any value from here.'])})
    return recs
def mh_registry():
    kind = pick(['maintenance', 'access'])
    if kind == 'maintenance':
        alias = pick(['Otter', 'Heron', 'Lynx', 'Sable', 'Kestrel-2', 'Puffin']); press = f"press P{rint(3, 30)}, generation G{rint(2, 5)}"; gen = press.split('generation ')[1]; fault = f"F-{pick(['INK', 'JAM', 'TMP', 'VIB'])}"; cls = pick(['A', 'B', 'C'])
        thr = pick([20, 30, 45, 60]); downtime = rint(thr - 15, thr + 25); bypass = rint(3, 20); shift = pick(['night', 'day']); approved = chance(.75); restored = chance(.7); has_bypass = chance(.85)
        fn_shift = pick(['night', 'day']); qualifies = has_bypass and approved and restored and shift == fn_shift
        adjusted = downtime - (bypass if qualifies else 0); strict = pick(['under', 'at most'])
        if has_bypass and not restored: truth = 'safety_shutdown'
        else: truth = 'local_maintenance' if (adjusted < thr if strict == 'under' else adjusted <= thr) else 'central_engineering'
        st = {'asset_map': {alias: press}, 'fault_map': {fault: f"{pick(['sensor contamination', 'feeder misalignment', 'thermal drift'])}, class {cls}"},
              'response_table': {f"class_{cls}": f"local maintenance if {strict} {thr} minutes; central engineering otherwise*"},
              'footnotes': {'*': f"For {gen} presses on {fn_shift} shift, approved bypass time is excluded from downtime when the bypass restores safe operation. A bypass that does not restore safe operation triggers safety shutdown regardless of duration."},
              'calculation_rule': f"Subtract only qualifying bypass duration before comparing '{strict} {thr}'; exactly {thr} {'is not under' if strict == 'under' else 'is at most'} {thr}.",
              'maintenance': {'machine_alias': alias, 'fault_code': fault, 'downtime_minutes': downtime, 'shift': shift, 'temporary_bypass': has_bypass},
              'bypass_log': ({'approved': approved, 'duration_minutes': bypass, 'restored_safe_operation': restored} if has_bypass else {'entry': 'none'}),
              'archive': archive_block('Maintenance', alias, fault, rint(2, 6))}
        opts = {'local_maintenance': f"After the qualifying subtraction, downtime is {strict} {thr} minutes, so local maintenance handles it.", 'central_engineering': f"After the qualifying subtraction, downtime is {'at least' if strict == 'under' else 'more than'} {thr} minutes, so central engineering handles it.", 'safety_shutdown': 'The bypass failed to restore safe operation, so safety shutdown applies.', 'insufficient_log': 'A fact needed for the decision is missing from the live records.'}
    else:
        ds = pick(['HARBOR', 'LANTERN', 'QUARRY', 'MERIDIAN']); group = pick(['field fellows', 'visiting analysts', 'audit interns']); cls = pick(['A2', 'B1', 'C3']); tier = pick(['amber', 'red', 'green'])
        default_days = pick([30, 45, 60]); ext_days = default_days * 2; requested = pick([default_days, default_days + 15, ext_days, ext_days + 10]); purpose = pick(['aggregate trend report', 'quarterly dashboard refresh']); code = 'RPT'
        non_gran = ['monthly totals', 'quarter', 'category']; moved = pick(['region', 'site', 'segment']); rev4_moved_to_nongran = chance(.6)
        if rev4_moved_to_nongran: non_gran.append(moved)
        fields = ['monthly totals', moved] if chance(.7) else ['monthly totals', 'quarter']; all_ng = all(f in non_gran for f in fields); tier_allowed = chance(.85)
        if not tier_allowed: truth = 'deny_sensitive'
        else:
            maxd = ext_days if (all_ng and purpose == 'aggregate trend report') else default_days
            truth = 'approve_as_requested' if requested <= maxd else 'reduce_to_default' if requested > maxd else 'approve_as_requested'
            if requested > default_days and requested <= maxd: truth = 'approve_as_requested'
            elif requested > maxd: truth = 'reduce_to_default'
        st = {'group_aliases': {group: f"affiliate class {cls}"}, 'dataset_registry': {ds: f"collection D{rint(2, 9)}, sensitivity tier {tier}"},
              'access_matrix': {tier: {cls: (f"aggregate only, maximum {default_days} days^7" if tier_allowed else 'no access'), 'E1': 'row-level, 90 days'}},
              'footnotes': {'7': f"{cls} maximum is {ext_days} days for purpose code {code} when every requested field is on the non-granular list."},
              'amendment': f"Revision 4 {'moved ' + moved + ' from the granular list to the non-granular list' if rev4_moved_to_nongran else 'left ' + moved + ' on the granular list'}; revision 4 is current.",
              'non_granular': non_gran, 'purpose_codes': {'aggregate trend report': 'RPT', 'quarterly dashboard refresh': 'DSH'},
              'data_request': {'dataset': ds, 'requester_group': group, 'fields': fields, 'purpose': purpose, 'retention_days': requested},
              'archive': archive_block('Data Access', ds, moved, 3)}
        opts = {'approve_as_requested': 'The matrix (with any footnote that applies) permits the requested fields and duration.', 'reduce_to_default': 'Only the default duration applies; the request is cut to it.', 'deny_sensitive': 'The requester class cannot access this tier.', 'needs_field_review': 'At least one requested field lacks a classification.'}
    instr = pick(["Trace the live mappings and footnotes and pick the one operative result.", "Follow alias → registry → matrix → footnote → rule, ignoring archived material, and choose the operative outcome.", "Resolve the request through the live tables and footnotes; what is the result?"])
    return choice(st, instr, opts, truth, bal=f"{kind}:{truth}")

