# ================================================================== routing_tradeoff
def rt_precedence():
    co = pick(COMPANIES); plan = pick(['Enterprise', 'Business', 'Team']); org = f"ORG-{rint(1000, 9999)}"; tn_main = f"tn_{rint(1000, 9999)}"; tn_sub = f"tn_{rint(1000, 9999)}"
    other_org_data = chance(.3); outage = chance(.2); repro = chance(.6); defect = chance(.7); refund = chance(.6)
    r1 = other_org_data; r2 = outage and plan == 'Enterprise'; r3 = defect and repro and plan in ('Business', 'Enterprise'); r4 = refund
    truth = 'escalate_to_security' if r1 else 'page_oncall' if r2 else 'escalate_to_engineering' if r3 else 'process_refund' if r4 else 'send_kb_article'
    msg = []
    if defect: msg.append(f"our scheduled export of the '{pick(['Q3 Pipeline', 'Weekly Churn', 'Renewals'])}' report fails with error EXP-{rint(100, 999)}" + (f" ({pick(['Reports > Export > CSV', 'API POST /v2/exports'])} — dies at about {rint(60, 95)}%)" if repro else " (it just doesn't work; no steps, happens randomly)"))
    if other_org_data: msg.append(f"the one CSV that did come through had {rint(50, 400)} rows tagged with an org we've never heard of (ORG-{rint(1000, 9999)}) — that's someone else's data in our file")
    elif chance(.5): msg.append(f"the CSV contained {rint(50, 400)} rows tagged tenant {tn_sub}, which is NOT our main workspace ({tn_main}) — is that somebody else's data?!")
    if outage: msg.append("also right now nobody in our company can log in or load any dashboard at all")
    elif chance(.4): msg.append("one of our users had trouble logging in this morning but it's fine now")
    if refund: msg.append("frankly we expect a service credit for this month")
    st = para(f"{co.upper()} — SUPPORT ROUTING POLICY SP-{rint(2, 9)} (rev. {rint(3, 9)})", '',
              "Precedence: when more than one rule applies, the agent performs ONLY the action of the highest-ranked applicable rule now; lower-ranked items are noted on the ticket for later.",
              "R1  Cross-organization data exposure — the customer can see data belonging to a DIFFERENT organization. Action: escalate to Security (escalate_to_security).", "R2  Active outage — no user of an Enterprise organization can log in or load dashboards. Action: page the on-call SRE (page_oncall).",
              "R3  Functional defect with reproducible steps, reported by a Business or Enterprise organization. Action: escalate to Product Engineering (escalate_to_engineering).", "R4  Billing dispute, credit or refund request. Action: billing queue (process_refund).", "R5  Anything else: send the matching knowledge-base article (send_kb_article).", '',
              'Definitions', f"- \"Organization\" means the billing entity identified by an Org ID. An organization may own several workspaces, each with its own tenant ID (tn_...). Workspaces sharing an Org ID are the SAME organization for every rule, even when their tenant IDs differ.",
              "- \"Reproducible steps\" means the customer describes a click path or API call that produces the failure.", "- \"Active outage\" means the condition exists at the time of the ticket, not a past or single-user incident.", '',
              f"TICKET #{rint(10000, 99999)}   opened {rand_date(2026, 6, 2027, 3)} {rint(8, 18):02d}:{rint(0, 59):02d}   channel: {pick(['email', 'portal'])}", f"Requester: {person()} ({pick(['Head of RevOps', 'IT lead', 'Finance manager'])})", f"Org ID: {org}      Plan: {plan}",
              f"Workspaces on this Org ID: {tn_main} \"Main\"; {tn_sub} \"{pick(['EU Subsidiary', 'Sandbox', 'APAC'])}\".", f"Service health (status page): {'all systems operational' if not outage else 'login degraded for some regions'}. Telemetry: {rint(20, 80) if not outage else 0} distinct users of {org} loaded dashboards in the last hour.", '',
              'Message:', '"Hi, ' + '; '.join(msg) + '. Please treat this as a priority."')
    opts = {'escalate_to_security': "R1 applies: the customer can see another organization's data.", 'page_oncall': 'R2 applies: an active outage for an Enterprise organization.', 'escalate_to_engineering': 'R3 is the highest-ranked applicable rule: a reproducible defect from a Business/Enterprise org.', 'process_refund': 'R4 is the highest-ranked applicable rule: route the credit request to billing now.', 'send_kb_article': 'R5 is the only rule that applies.'}
    instr = pick(["Apply the support routing policy to the ticket and choose the single action the agent must take now.", "Under the precedence rule, which one action does the ticket require now?", "Which rule ranks highest among those that actually apply to this ticket?"])
    return choice(st, instr, opts, truth)

