def rt_handler():
    hs = pick(HANDLER_SETS); truth = pick(list(hs['handlers'])); case = pick(hs['cases'][truth]); decoy = pick([h for h in hs['handlers'] if h != truth])
    cue = pick([f"I think this is really a {decoy.replace('_', ' ')} issue", f"our IT guy says {decoy.replace('_', ' ')} should look at it", "not sure who owns this"])
    req = f"{pick(['Our analyst', 'A colleague', 'The finance team', 'One of our branches'])} reports: {case}. {cue}. {pick(['Please keep the data intact.', 'We need this before the close.', 'Any help appreciated.'])}"
    st = {'handlers': dict(hs['handlers']), 'request': req} if chance(.7) else para('Available handlers:', *[f"- {k}: {v}" for k, v in hs['handlers'].items()], '', 'Request:', req)
    instr = pick(["Pick the single handler that should own this request as primary.", "Which handler owns this request as its primary?", "Route the request to the one handler whose remit matches the actual symptom."])
    return choice(st, instr, dict(hs['handlers']), truth, bal=f"{hs['domain']}:{truth}")

