def ta_disposition():
    co = pick(COMPANIES); cust = pick(['confirms fixed', 'reports persists', 'no reply', 'no reply']); agent_ok = chance(.8); days = rint(1, 9); wait = pick([3, 5, 7])
    truth = 'close_confirmed' if cust == 'confirms fixed' else 'keep_open_unresolved' if cust == 'reports persists' else ('close_after_silence' if days >= wait else 'await_customer')
    st = para(f"{co.upper()} — TICKET CLOSURE RULE", f"A ticket is closed only when the customer confirms the issue is resolved, or when the customer has not replied for {wait} full days after the agent's last fix notice. Agent-side telemetry alone never closes a ticket. A customer statement that the problem persists keeps the ticket open even if telemetry looks clean.", '',
              f"Ticket #{rint(10000, 99999)}: agent applied a fix; agent-side telemetry {'shows the error gone' if agent_ok else 'is inconclusive'}.",
              f"Customer response since the fix notice ({days} days ago): " + {'confirms fixed': 'customer wrote "confirmed, working now, thanks"', 'reports persists': 'customer wrote "still failing for us every morning"', 'no reply': 'none'}[cust] + '.',
              note('draft', 'Telemetry is clean — closing as verified.') if truth != 'close_confirmed' else note('lead', 'Check the closure rule before you close.'))
    opts = {'close_confirmed': 'Close: the customer confirmed the fix worked.', 'close_agent_verified': 'Close because agent-side telemetry alone meets the closure rule.', 'keep_open_unresolved': 'Keep open because the customer reports the issue persists.', 'await_customer': f'Neither close nor keep open indefinitely: the {wait}-day silence period has not elapsed.', 'close_after_silence': f'Close because the customer has been silent for at least {wait} full days after the fix notice.'}
    instr = pick(["Pick the ticket disposition the closure rule requires.", "Under the closure rule, what happens to the ticket now?", "Select the disposition the rule requires."])
    return choice(st, instr, opts, truth)

