# ================================================================== noul_yesno
def ny_policy():
    act = pick([('issue a refund above the agent limit', ['the order is within 30 days of delivery', 'the customer has no open chargeback', 'a supervisor code is attached'], 'refunds on final-sale items'),
                ('grant remote access to the finance share', ['the requester has completed security training this year', 'the line manager has approved in writing', 'the device is company-managed'], 'access from a personal device'),
                ('extend the contractor engagement', ['the current engagement has fewer than 30 days left', 'budget cover is confirmed by the cost-centre owner', 'a background check is on file'], 'extensions past 24 months of continuous engagement'),
                ('waive the late fee', ['this is the customer\'s first late payment in 12 months', 'the payment arrived within 5 days of the due date', 'the account is not in collections'], 'waivers on accounts with a payment plan'),
                ('ship the replacement before the return arrives', ['the item value is below the advance-replacement limit', 'a card is on file for the security hold', 'the account is at least 6 months old'], 'advance replacement of clearance items')])
    action, conds, prohib = act; est = [chance(.7) for _ in conds]; prohibited = chance(.25); truth = all(est) and not prohibited
    if not truth and all(est) and not prohibited: return None
    facts = []
    for c, e in zip(conds, est):
        facts.append(c[0].upper() + c[1:] + '.' if e else pick([f"Whether {c} is not stated.", f"The agent believes {c}, but no record shows it.", f"It was true last year that {c}; nothing shows it now."]))
    if prohibited: facts.append(pick([f"The case involves {prohib.split(' on ')[-1] if ' on ' in prohib else prohib}.", f"This is one of the {prohib}."]))
    elif chance(.4): facts.append(f"The case does not involve {prohib}.")
    st = para(f"Policy: an agent may {action} only if " + ', '.join(conds[:-1]) + f", and {conds[-1]}. The policy prohibits {prohib}.", 'Facts: ' + ' '.join(shuffled(facts)), f"Request: the agent wants to {action}.")
    instr = pick(["Under the stated policy, is the requested action permitted? Treat any required condition that is not proved as not satisfied.", "Is the action allowed by the policy as written? Unproven conditions count as unmet.", "Applying the policy strictly to the stated facts, may the agent proceed?"])
    return noul(st, instr, "All required conditions are shown to hold and no prohibition applies.", "A required condition is unproven or missing, or a prohibition applies.", truth)

def ny_fact():
    subj = pick([('the order', 'been shipped', 'shipped', 'ship'), ('the invoice', 'been paid', 'paid', 'pay'), ('the report', 'been submitted', 'submitted', 'submit'), ('the contract', 'been signed', 'signed', 'sign'), ('the server', 'been rebooted', 'rebooted', 'reboot')])
    thing, q, done, verb = subj; truth = chance(.5)
    if truth: text = pick([f"{thing.capitalize()} was {done} on {wd(rand_date(2026, 3, 2026, 11))}; the confirmation number is {rint(10000, 99999)}.", f"Although the team had planned to wait, they {verb}{'ped' if verb.endswith('p') else 'ed'} {thing} yesterday after the client called.", f"Update: {thing} is now {done}. Earlier notes saying otherwise are out of date."])
    else: text = pick([f"{thing.capitalize()} has not been {done}; the team expects to {verb} it on {wd(rand_date(2026, 3, 2026, 11))}.", f"Had the approval come through, {thing} would have been {done} by now.", f"The system shows {thing} as \"ready to {verb}\"; nothing further has happened.", f"{thing.capitalize()} was scheduled to be {done} last week, but the note says the slot was cancelled."])
    st = text + ' ' + pick(['Everyone has been informed.', 'A follow-up call is booked.', 'No further action is logged.', ''])
    instr = pick([f"Has {thing} {q}? Answer only from what the text states.", f"Based strictly on the stated facts, has {thing} {q}?", f"Does the text state that {thing} has {q}?"])
    return noul(st.strip(), instr, "The text states that this has happened.", "The text does not state that this has happened (it is denied, planned, hypothetical or unstated).", truth)

def ny_adequacy():
    kind = pick(['words', 'sentences', 'contains', 'uppercase', 'question', 'items', 'decimals', 'reference'])
    if kind == 'words':
        n = rint(2, 6); words = sample(['done', 'all', 'set', 'ready', 'now', 'fine', 'sent', 'ok', 'today', 'thanks'], n + rint(-1, 1) if chance(.5) else n); req = f"Reply in exactly {n} words."; resp = ' '.join(words).capitalize(); truth = len(words) == n
    elif kind == 'sentences':
        n = rint(1, 3); k = n + pick([0, 0, 1, -1]); k = max(1, k); resp = ' '.join(pick(['The shipment left on time.', 'We will confirm by Friday.', 'The invoice is attached.', 'No action is needed.']) for _ in range(k)); req = f"Answer in exactly {n} sentence{'s' if n > 1 else ''}."; truth = k == n
    elif kind == 'contains':
        w = pick(['budget', 'deadline', 'approved', 'refund']); inc = chance(.5); resp = f"The {w if inc else pick(['plan', 'schedule', 'file'])} was discussed and the team agreed to proceed."; req = f"Write one sentence that includes the word \"{w}\"."; truth = inc
    elif kind == 'uppercase':
        ok = chance(.5); resp = 'ALL SYSTEMS NOMINAL' if ok else 'All systems nominal'; req = 'Answer entirely in capital letters.'; truth = ok
    elif kind == 'question':
        ok = chance(.5); resp = 'Could you send the revised figures by noon' + ('?' if ok else '.'); req = 'Reply with a single question ending in a question mark.'; truth = ok
    elif kind == 'items':
        n = rint(2, 5); k = n + pick([0, 0, 1, -1]); k = max(1, k); resp = '\n'.join(f"- {pick(['milk', 'bread', 'eggs', 'rice', 'tea', 'salt', 'oats'])}" for _ in range(k)); req = f"List exactly {n} items as bullet points."; truth = k == n
    elif kind == 'decimals':
        d = rint(1, 3); k = d + pick([0, 0, 1, -1]); k = max(0, k); v = rr(1, 90); resp = f"The result is {v:.{k}f} kg."; req = f"State the mass in kilograms to {d} decimal place{'s' if d > 1 else ''}."; truth = k == d
    else:
        y = rint(2018, 2025); ok = chance(.5); req = f"Using the reference, state the year the plant opened. Reference: the plant opened in {y}."; resp = f"The plant opened in {y if ok else y + pick([-1, 1, 2])}."; truth = ok
    st = pick([f"Request: {req} Response: {resp}", f"Request: {req}\nResponse: {resp}", json.dumps({'request': req, 'response': resp})])
    instr = pick(["Does the response satisfy the request completely, including every explicit constraint and the supplied reference where present?", "Judge the response against the request's explicit constraints: is it fully adequate?", "Is the response a complete and constraint-compliant answer to the request?"])
    return noul(st, instr, "Correct, complete and compliant with every explicit constraint.", "Wrong, incomplete, unsupported or in breach of a constraint.", truth, bal=f"{kind}:{truth}")

NOUL_FAM = [ny_policy, ny_fact, ny_adequacy]

# ================================================================== score_levels
def sl_impact():
    lvl = rint(0, 3); levels = ['Nothing functional is impaired; purely cosmetic', 'One user or a non-essential function impaired, with a workaround', 'Many users are blocked from a core function; no data has been lost', 'Irreversible data loss or physical harm is confirmed']
    facts = {0: [f"A {pick(['logo', 'tooltip', 'footer'])} renders {pick(['misaligned', 'in the wrong colour'])} on one page; every function works."], 1: [f"{pick(FIRST)} cannot open the {pick(['export', 'archive', 'preferences'])} panel; other users are unaffected and the panel is reachable via the old menu."], 2: [f"{rint(40, 900)} users cannot {pick(['log in', 'submit orders', 'load the ledger'])}; no records were lost."], 3: [f"{rint(2, 40)} customer records were {pick(['overwritten', 'deleted'])} and the backup does not contain them."]}[lvl]
    facts.append(pick([f"A customer speculates that data may be lost, but nothing confirms it.", f"An engineer worries this could spread to all users; so far it has not.", "The status page was updated.", ""]))
    st = ' '.join(f for f in shuffled(facts) if f); instr = pick(["Rate incident impact using only reported facts; use the highest fully supported level.", "Assign the impact level that the reported facts fully support (not what might happen).", "Which impact level is established by the facts as stated?"])
    return score(st, instr, levels, lvl)

def sl_count():
    kind = pick(['late', 'overweight', 'temp']); n = rint(5, 9); rows = []; count = 0
    for i in range(n):
        if kind == 'late':
            due = rint(9 * 60, 16 * 60); actual = due + rint(-40, 80); grace = 15; late = actual > due + grace; rows.append([f"{ref('DL', 3)}", hm(due), hm(actual)]); count += late
        elif kind == 'overweight':
            lim_kg = 25; w = r2(rr(18, 34)); unit = pick(['kg', 'lb']); shown = w if unit == 'kg' else r2(w * 2.20462); over = (shown if unit == 'kg' else shown * 0.45359) > lim_kg + 1e-9; rows.append([f"{ref('PK', 3)}", f"{shown} {unit}"]); count += over
        else:
            lo, hi = 2, 8; t = r2(rr(-1, 11)); unit = pick(['°C', '°F']); shown = t if unit == '°C' else r2(t * 9 / 5 + 32); tc = shown if unit == '°C' else (shown - 32) * 5 / 9; out = tc < lo - 1e-9 or tc > hi + 1e-9; rows.append([f"{ref('RD', 3)}", f"{shown} {unit}"]); count += out
    rule = {'late': 'A delivery is late if the actual arrival is more than 15 minutes after the due time; exactly 15 minutes is on time.', 'overweight': 'A parcel breaches the limit if its mass exceeds 25 kg (1 lb = 0.45359 kg exactly for this check); exactly 25 kg complies.', 'temp': 'A reading is out of range if below 2 °C or above 8 °C (convert Fahrenheit readings: °C = (°F − 32) × 5/9); the limits themselves are in range.'}[kind]
    cols = {'late': ['Delivery', 'Due', 'Actual'], 'overweight': ['Parcel', 'Mass'], 'temp': ['Reading', 'Value']}[kind]
    st = para(rule, '', md_table(cols, rows), '', note('draft', f"I make it {max(0, count + pick([-1, 1, 2]))} breaches.") if chance(.6) else '')
    instr = pick(["How many entries breach the rule? Output 0, 1, 2, or 3 for three or more.", "Count the breaches under the stated rule (3 = three or more).", "Apply the rule to every row and select the count band."])
    return score(st.strip(), instr, ['No breaches', 'Exactly one breach', 'Exactly two breaches', 'Three or more breaches'], min(count, 3), bal=f"{kind}:{min(count, 3)}")

def sl_shortfall():
    kind = pick(['seats', 'stock', 'staff']); need = rint(40, 200); band = rint(0, 3); short = {0: rint(-10, 0), 1: rint(1, 5), 2: rint(6, 15), 3: rint(16, 40)}[band]; have = need - short
    adj = rint(-6, 6); have_shown = have - adj
    txt = {'seats': f"Required licences on the measurement date: {need}. Order forms in force on that date total {have_shown} licences; a further order of {rint(5, 20)} licences starts the day after. {'An additional ' + str(adj) + ' licences were added by an order that started before the measurement date but were left off the summary.' if adj > 0 else ('The summary double-counts ' + str(-adj) + ' licences that were cancelled before the date.' if adj < 0 else 'The summary is complete.')}",
           'stock': f"Committed orders for tomorrow need {need} units. The warehouse system shows {have_shown} units. {'A late receipt of ' + str(adj) + (' unit' if adj == 1 else ' units') + ' was booked after the report ran and is available tomorrow.' if adj > 0 else ('Of the units shown, ' + str(-adj) + (' is' if adj == -1 else ' are') + ' quarantined and cannot ship.' if adj < 0 else 'No adjustments are pending.')}",
           'staff': f"The rota needs {need} shifts covered this week. Confirmed staff cover {have_shown} shifts. {'Agency staff confirmed this morning add ' + str(adj) + ' shifts.' if adj > 0 else (str(-adj) + ' of the confirmed shifts were withdrawn this morning.' if adj < 0 else 'No changes since the plan.')}"}[kind]
    levels = ['No shortfall (requirement fully covered)', 'Shortfall of 1 to 5', 'Shortfall of 6 to 15', 'Shortfall of more than 15']
    instr = pick(["What is the shortfall band? Output the level index.", "Compute requirement minus available (after every stated adjustment) and select the band.", "Select the shortfall level that results."])
    return score(txt, instr, levels, band, bal=f"{kind}:{band}")

