# ================================================================== judge_verify
def jv_pair():
    kind = pick(['tank', 'area', 'busdays', 'density', 'discount_tax', 'pct_change', 'km_miles', 'average', 'time_diff'])
    err = pick([None, None, 'arith', 'round', 'unit', 'format', 'order'])
    if kind == 'tank':
        v0 = rint(50, 200); rate = r2(rr(0.8, 3.5)); h = pick([2.5, 4, 6, 7.5]); add = rint(5, 30); leak = r2(rate * h); mid = r2(v0 - leak); fin = r2(mid + add)
        req = f"A tank starts with {v0} liters. It leaks {rate} liters per hour for {h} hours, then {add} liters are added. Report the final volume in liters to one decimal place and show the calculation in chronological order."
        if err == 'arith': fin_s = f"{fin + pick([1, -1, 10]):.1f}"; mid_s = f"{mid:.1f}"
        else: fin_s = f"{fin:.1f}"; mid_s = f"{mid:.1f}"
        if err == 'round': fin_s = f"{fin:.2f}"
        if err == 'order': resp = f"Adding {add} liters to {v0} gives {v0 + add} liters; the leak removes {rate} × {h} = {leak} liters, leaving {fin_s} L."
        else: resp = f"The leak removes {rate} × {h} = {leak} liters. After the leak the tank has {v0} − {leak} = {mid_s} liters. Adding {add} liters gives {fin_s} liters. Final volume: {fin_s} L."
        if err == 'unit': resp = resp.replace('L.', 'gallons.')
        if err == 'format': resp = resp.replace('Final volume: ', 'Final: ').replace(f"{fin_s} L", f"about {round(fin)} L")
    elif kind == 'area':
        a = rint(100, 900); f2 = 0.3048 ** 2; exact = a * f2; d = 3
        req = f"Convert {a} square feet to square meters using exactly 1 foot = 0.3048 meter. Show how the squared conversion factor is applied and give the answer to {d} decimal places."
        val = f"{exact:.{d}f}"
        if err == 'round': val = f"{math.floor(exact * 10 ** d) / 10 ** d:.{d}f}" if f"{math.floor(exact * 10 ** d) / 10 ** d:.{d}f}" != f"{exact:.{d}f}" else f"{exact:.{d - 1}f}"
        if err == 'arith': val = f"{exact * 1.01:.{d}f}"
        if err == 'unit': resp = f"{a} ft × 0.3048 m/ft applied once: {a} × 0.3048 = {a * 0.3048:.{d}f} m²."
        elif err == 'format': resp = f"{a} ft² × (0.3048)² = {exact:.6f} m²."
        elif err == 'order': resp = f"The answer is {val} m²; this comes from {a} × 0.09290304, i.e. the factor 0.3048 squared."
        else: resp = f"Because the measurement is area, the factor is applied twice: {a} ft² × (0.3048 m/ft)² = {a} × 0.09290304 m² = {exact:.6f} m². To {d} decimal places: {val} m²."
        if err == 'order': err = None
    elif kind == 'busdays':
        start = rand_date(2025, 10, 2026, 6)
        while start.weekday() >= 5: start += TD(days=1)
        n = rint(5, 9); hol = [d for d in [start + TD(days=rint(2, 6))] if d.weekday() < 5]; d = start; days = []
        while len(days) < n:
            d += TD(days=1)
            if d.weekday() < 5 and d not in hol: days.append(d)
        req = f"Starting {wd(start)}, {d_us(start)}, add {n} business days. Count the start as day 0; business days are Monday–Friday" + (f", and {wd(hol[0])} {d_us(hol[0])} is a holiday" if hol else '') + ". State the resulting date and list the counted business days."
        listed = list(days)
        if err in ('arith', 'order'):
            listed = days[:-1] + [days[-1] + TD(days=1 if days[-1].weekday() < 4 else 3)]; err = 'arith'
        if err == 'round': listed = days[:-1] + [days[-1] - TD(days=1)] if len(days) > 1 else listed; err = 'arith' if listed[-1] != days[-1] else None
        if err == 'unit':
            hol_used = hol[0] if hol else None; err = None
            if hol_used: listed = sorted(days[:n - 1] + [hol_used]); err = 'arith'
        resp = "Counted days are " + ', '.join(f"{wd(x)[:3]} {MONTHS[x.month - 1][:3]} {x.day} ({i + 1})" for i, x in enumerate(listed)) + f". Result: {wd(listed[-1])}, {d_us(listed[-1])}."
        if err == 'format': resp = f"Result: {d_us(listed[-1])}."
    elif kind == 'density':
        m = r2(rr(1.2, 4.8)); v = rint(600, 2500); g = m * 1000 / v; kg = g * 1000
        req = f"A lab sample has mass {m:.2f} kg and volume {v:,} cm³. Calculate density in g/cm³ and kg/m³, show the conversion, and give both answers to three significant figures."
        f1 = sig3(g); f2_ = sig3(kg); conv = '1 g/cm³ equals 1000 kg/m³'
        if err == 'unit': f2_ = sig3(g * 100); conv = '1 g/cm³ equals 100 kg/m³'
        if err == 'arith': f1 = sig3(g * 1.05); f2_ = sig3(g * 1.05 * 1000)
        if err == 'round': f1 = f"{g:.4f}"
        resp = f"{m:.2f} kg = {m * 1000:,.0f} g. Density = {m * 1000:,.0f} g / {v:,} cm³ = {f1} g/cm³. Since {conv}, this is {f2_} kg/m³ (three significant figures)."
        if err == 'format': resp = f"Density is {f1} g/cm³, which is {f2_} kg/m³."
        if err == 'order': err = None
    elif kind == 'discount_tax':
        sub = r2(rr(10, 300)); dpct = pick([10, 15, 20, 12.5]); tpct = pick([8.25, 7.5, 6, 9.75]); base = sub * (1 - dpct / 100); taxed = base * (1 + tpct / 100)
        from decimal import Decimal, ROUND_HALF_UP
        fin = Decimal(str(round(taxed, 10))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        req = f"An invoice subtotal is ${sub:.2f}. Apply a {dpct}% discount, then {tpct}% tax to the discounted amount. Do not round the intermediate discounted amount. Round the final charge to cents using half-up, and show the derivation."
        val = f"{fin}"
        if err == 'round': val = f"{math.floor(taxed * 100) / 100:.2f}" if f"{math.floor(taxed * 100) / 100:.2f}" != val else f"{float(fin) + 0.01:.2f}"
        if err == 'arith': val = f"{float(fin) + pick([0.1, 1, -0.5]):.2f}"
        if err == 'unit': val = f"{taxed:.2f} (rounded)".replace(f"{taxed:.2f}", f"{taxed:.4f}"); err = 'format'
        resp = f"Discounted amount = {sub:.2f} × {1 - dpct / 100:g} = {base:.6f}. Taxed charge = {base:.6f} × {1 + tpct / 100:g} = {taxed:.8f}. Rounded half-up to cents, the final charge is ${val}."
        if err == 'format': resp = f"Discounted amount = {round(base, 2):.2f}; with tax {round(base, 2) * (1 + tpct / 100):.2f}; final ${val}."
        if err == 'order': err = None
    elif kind == 'pct_change':
        a = rint(200, 9000); b = rint(200, 9000); ch = (b - a) / a * 100; d = 1
        req = f"A metric moved from {a:,} to {b:,}. State the percentage change relative to the starting value, to one decimal place, with the sign."
        val = f"{ch:+.{d}f}%"
        if err == 'arith': val = f"{(b - a) / b * 100:+.1f}%"
        if err == 'round': val = f"{ch:+.3f}%"
        if err == 'format': val = f"{abs(ch):.1f}%"
        if err == 'unit': val = f"{ch / 100:+.3f}"
        resp = f"Change = ({b:,} − {a:,}) / {a:,} × 100 = {val}."
        if err == 'order': err = None
    elif kind == 'km_miles':
        km = r2(rr(3, 400)); mi = km * 0.621371; d = 2
        req = f"Convert {km} km to miles using 1 km = 0.621371 mi; give the result to two decimal places with the unit."
        val = f"{mi:.2f} mi"
        if err == 'arith': val = f"{km / 0.621371:.2f} mi"
        if err == 'round': val = f"{mi:.3f} mi"
        if err == 'unit': val = f"{mi:.2f} km"
        if err == 'format': val = f"{mi:.2f}"
        resp = f"{km} × 0.621371 = {val}."
        if err == 'order': err = None
    elif kind == 'average':
        xs = [rint(10, 99) for _ in range(rint(4, 6))]; avg = sum(xs) / len(xs)
        req = f"Compute the arithmetic mean of {', '.join(map(str, xs))} to two decimal places, showing the sum and the divisor."
        val = f"{avg:.2f}"
        if err == 'arith': val = f"{(sum(xs) + pick([3, -5, 10])) / len(xs):.2f}"
        if err == 'round': val = f"{math.floor(avg * 100) / 100:.2f}" if f"{math.floor(avg * 100) / 100:.2f}" != val else f"{avg:.1f}"
        if err == 'unit': val = f"{sum(xs) / (len(xs) - 1):.2f}"; err = 'arith'
        resp = f"Sum = {sum(xs)}; divisor = {len(xs)}; mean = {val}."
        if err == 'format': resp = f"The mean is {val}."
        if err == 'order': err = None
    else:
        h1, m1 = rint(6, 11), pick([0, 15, 30, 45]); h2, m2 = rint(12, 20), pick([0, 15, 30, 45]); mins = (h2 * 60 + m2) - (h1 * 60 + m1)
        req = f"A shift runs from {h1:02d}:{m1:02d} to {h2:02d}:{m2:02d} the same day. State its length in hours and minutes and also as a decimal number of hours to two decimal places."
        hh, mm = divmod(mins, 60); dec = f"{mins / 60:.2f}"
        if err == 'arith': mm = (mm + 15) % 60; dec = f"{(hh * 60 + mm) / 60:.2f}"
        if err == 'round': dec = f"{mins / 60:.1f}"
        if err == 'unit': dec = f"{mins}"
        resp = f"{h2:02d}:{m2:02d} − {h1:02d}:{m1:02d} = {hh} h {mm} min = {dec} hours."
        if err == 'format': resp = f"{hh} hours and {mm} minutes."
        if err == 'order': err = None
    truth = err is None
    st = {'request': req + (pick(['', '', "\n\nEvaluation context: the answer is reviewed as a complete handoff; intermediate reasoning, units, rounding conventions and every stated presentation constraint matter independently of whether the final number looks plausible."])), 'response': resp}
    instr = pick(["Judge whether the response meets every explicit requirement of the request, without any substantive error.", "Check the derivation, arithmetic, units, rounding and formatting: is the response fully correct and complete?", "Is this response a fully correct and complete answer to the request as stated?"])
    return noul(st, instr, "The response is fully correct and satisfies every explicit constraint (method, units, rounding, formatting, listed facts).", "The response contains a substantive error or misses an explicit constraint.", truth, bal=f"{kind}:{truth}")

