# ================================================================== probability_freq
def pf_conditional():
    co = pick(COMPANIES); causes = pick([['bad_push', 'upstream_provider', 'database_hardware'], ['config_drift', 'traffic_spike', 'storage_fault'], ['courier_delay', 'customs_hold', 'address_error']])
    labels = {'bad_push': 'A faulty configuration or code deployment.', 'upstream_provider': 'Slowness at the upstream provider.', 'database_hardware': 'A database host or storage hardware failure.', 'config_drift': 'Configuration drift on a node.', 'traffic_spike': 'An unexpected traffic spike.', 'storage_fault': 'A storage-layer fault.', 'courier_delay': 'Courier network delay.', 'customs_hold': 'A customs inspection hold.', 'address_error': 'A wrong or incomplete address.'}
    cond = pick([('deploy in the prior 2 h', 'no deploy in the prior 2 h', 'deploy'), ('order placed on a weekend', 'order placed on a weekday', 'weekend')])
    while True:
        tab = {c: [rint(1, 30), rint(1, 30)] for c in causes}
        tot = {c: sum(v) for c, v in tab.items()}; overall = max(causes, key=lambda c: tot[c]); col = rint(0, 1)
        colvals = {c: tab[c][col] for c in causes}; best = max(causes, key=lambda c: colvals[c])
        if sorted(colvals.values())[-1] > sorted(colvals.values())[-2] and sorted(tot.values())[-1] > sorted(tot.values())[-2]: break
    if cond[2] == 'deploy':
        alert = DT(2026, rint(1, 12), rint(1, 28), rint(6, 22), rint(0, 59)); gap = rr(0.3, 1.9) if col == 0 else rr(2.1, 7); dep = alert - TD(hours=gap)
        newev = f"NEW ALERT — {alert.strftime('%Y-%m-%d %H:%M')} UTC. Deploy log: last production deploy {dep.strftime('%H:%M')} UTC the same day; no deploys since."
    else:
        d = rand_date(2026, 1, 2026, 12)
        while (d.weekday() >= 5) != (col == 0): d += TD(days=1)
        newev = f"NEW CASE — order placed {wd(d)} {d_us(d)}."
    rows = [[labels[c].rstrip('.'), tot[c], tab[c][0], tab[c][1]] for c in causes] + [['Total', sum(tot.values()), sum(v[0] for v in tab.values()), sum(v[1] for v in tab.values())]]
    st = para(f"{co.upper()} — REFERENCE STATISTICS for {pick(['alert pattern LAT-9', 'late-delivery cases', 'incident class P3'])}", '', f"All {sum(tot.values())} cases with a confirmed cause, broken down by whether there was a {cond[0]} or {cond[1]}.", '',
              md_table(['Confirmed cause', 'Cases', f"…{cond[0]}", f"…{cond[1]}"], rows), '', "Guidance: estimate the cause probabilities from this table, conditioning on every attribute of the new case that the table breaks down by. Assume the new case is drawn from the same population.", '', newev,
              note('chat', f"It's almost always {labels[overall].rstrip('.').lower()} ({tot[overall] / sum(tot.values()) * 100:.0f}% of the time)."))
    instr = pick(["What is the most likely cause of the new case? Give probabilities that reflect the reference data and the guidance.", "Conditioning as the guidance requires, which cause is most probable for the new case?", "Using the table and the new case's attributes, select the most likely cause."])
    return choice(st, instr, {c: labels[c] for c in causes}, best, bal=f"{'same' if best == overall else 'diff'}")

def pf_filtered():
    co = pick(COMPANIES); carriers = sample(['Brisa Freight', 'Kolt Logistics', 'Marrow Lines', 'Ostvik Cargo'], 2); services = ['Express', 'Economy']; outs = ['early', 'on time', 'late']
    target = (carriers[0], 'Express'); peak = (47, 52)
    while True:
        rows = []
        for i in range(rint(24, 32)):
            c = pick(carriers) if chance(.4) else carriers[0]; s = pick(services) if chance(.35) else 'Express'; wk = rint(10, 52); o = pick(outs); rows.append((f"SH-{4400 + i}", c, s, wk, o))
        filt = [r for r in rows if r[1] == target[0] and r[2] == target[1] and not (peak[0] <= r[3] <= peak[1])]
        cnt = collections.Counter(r[4] for r in filt); allc = collections.Counter(r[4] for r in rows if r[1] == target[0])
        if len(filt) >= 8 and len(cnt) >= 2 and sorted(cnt.values())[-1] > sorted(cnt.values())[-2] and sorted(allc.values())[-1] > sorted(allc.values())[-2]: break
    best = cnt.most_common(1)[0][0]; naive = allc.most_common(1)[0][0]
    st = para(f"{co.upper()} — INBOUND LOGISTICS: DELIVERY FORECAST FOR SHIPMENT {ref('SH')}", '', f"Shipment: {target[0]}, service {target[1]}, pickup week {rint(30, 44)}/2026, route {pick(['Porto', 'Gdańsk', 'Valencia'])} → {pick(['Hanover', 'Lyon', 'Utrecht'])}.",
              "Outcome categories: early (before the promised day), on time (on the promised day), late (after the promised day).", f"Method (planning handbook): estimate from past shipments on the same route with the same carrier and the same service level, excluding shipments picked up in peak weeks {peak[0]}–{peak[1]}. Use the frequencies directly.", '',
              'Past shipments on this route, 2025:', *[f"{r[0]} | {r[1]} | {r[2]} | pickup week {r[3]}/2025 | {r[4]}" for r in rows], '', note('chat', f"{target[0]} is {naive} a lot — I count {allc[naive]} {naive} out of their {sum(allc.values())}."))
    instr = pick(["What will the delivery outcome of the shipment be? Give probabilities that reflect the evidence in the state.", "Following the handbook method, which outcome is most likely for this shipment?", "Estimate the outcome from the qualifying history and select the most likely category."])
    return choice(st, instr, {'early': 'Delivered ahead of the promised day.', 'on_time': 'Delivered exactly on the promised day.', 'late': 'Delivered later than the promised day.'}, best.replace(' ', '_'), bal=f"{'same' if best == naive else 'diff'}")

PROB = [pf_conditional, pf_filtered]

# ================================================================== registry, writing, checking
FAMILIES = {'long_policy': [lp_procurement, lp_returns, lp_insurance, lp_licence, lp_relief, lp_incident], 'temporal_numeric': TEMPORAL, 'multi_hop': MULTIHOP, 'routing_tradeoff': ROUTING,
            'trap_adversarial': TRAP, 'noul_yesno': NOUL_FAM, 'score_levels': SCORE_FAM, 'judge_verify': JUDGE, 'probability_freq': PROB}

def generate(families, n):
    out = []
    for fam in families:
        gens = FAMILIES[fam]; per = [n // len(gens) + (1 if i < n % len(gens) else 0) for i in range(len(gens))]
        for g, k in zip(gens, per):
            rows = balanced(g, k)
            for r in rows:
                gid = f"synth_jevbench_{fam}/{hashlib.sha256((r['state'] + r['instructions']).encode()).hexdigest()[:16]}"
                out.append(dict(id=gid + '/0', group=gid, source=f"synth_jevbench_{fam}", state=r['state'], instructions=r['instructions'], criteria=r['criteria'], expected=r['expected'],
                                upstream_split='dev' if int(gid[-2:], 16) % 10 == 0 else 'train', _family=fam, _type=r['type'], _sub=g.__name__, _bal=r['bal']))
    return out

def load_reference():
    """Strings from the benchmark items and the frozen eval sets that nothing generated may overlap with."""
    strings = collections.defaultdict(set)
    def add(kind, s):
        if not isinstance(s, str) or not s: return
        strings[kind].add(s); strings[kind + '_prefix'].add(s[:120]); strings[kind + '_norm'].add(re.sub(r'\s+', ' ', s.lower())[:120])
    files = [BENCH_ITEMS] + sorted((REV).glob(EVAL_GLOB))
    for f in files:
        for line in f.read_text().splitlines():
            if not line.strip(): continue
            r = json.loads(line); st = r.get('state')
            for s in ([st] if isinstance(st, str) else [json.dumps(st, ensure_ascii=False), json.dumps(st, ensure_ascii=False, indent=1), json.dumps(st, ensure_ascii=False, indent=2)]): add('state', s)
            add('instructions', r.get('instructions'))
            for v in (r.get('criteria') or {}).values(): add('option', v if isinstance(v, str) else json.dumps(v))
    return strings, [str(f) for f in files]

def check(out_dir):
    rows = []
    for f in sorted(Path(out_dir).glob('*.jsonl')): rows += [json.loads(l) for l in f.read_text().splitlines() if l.strip()]
    ref_, files = load_reference(); bad = collections.Counter(); examples = []
    for r in rows:
        for kind, vals in [('state', [r['state']]), ('instructions', [r['instructions']]), ('option', list(r['criteria'].values()))]:
            for v in vals:
                hits = [t for t, s in [('exact', v in ref_[kind]), ('prefix120', v[:120] in ref_[kind + '_prefix']), ('norm120', re.sub(r'\s+', ' ', v.lower())[:120] in ref_[kind + '_norm'])] if s]
                for h in hits: bad[(kind, h)] += 1; examples.append((r['id'], kind, h, v[:100]))
    print(f"overlap check: {len(rows)} generated rows vs {len(files)} reference files ({', '.join(Path(f).name for f in files)})")
    print('  reference strings:', {k: len(v) for k, v in ref_.items() if not k.endswith(('_prefix', '_norm'))})
    for k, v in sorted(bad.items()): print('  OVERLAP', k, v)
    for e in examples[:10]: print('   ', e)
    assert not bad, 'overlap with benchmark items or eval sets'
    print('  no exact, 120-char-prefix or normalised-prefix overlap in states, instructions or option descriptions')
    fam = collections.defaultdict(collections.Counter); types = collections.defaultdict(collections.Counter); lens = collections.defaultdict(list)
    for r in rows:
        f = r['source'].replace('synth_jevbench_', ''); k = r['criteria']
        qt = 'noul' if set(k) == {'true', 'false'} else 'score' if all(x.isdigit() for x in k) else 'choice'
        fam[f][(qt + ':' + r['expected']) if qt != 'choice' else ('choice:' + r['expected'])] += 1; types[f][qt] += 1; lens[f].append(len(r['state']))
    print('\nper-family label balance (type:expected -> count; choice labels vary per item, so the 14 most common are shown), question types, state length (min/median/max chars):')
    for f in sorted(fam):
        L = sorted(lens[f]); top = sorted(fam[f].items(), key=lambda kv: (-kv[1], kv[0])); rest = sum(v for _, v in top[14:])
        print(f"  {f:18s} n={sum(fam[f].values()):5d}  types={dict(types[f])}  len={L[0]}/{L[len(L) // 2]}/{L[-1]}")
        print('      ' + ', '.join(f"{k}={v}" for k, v in top[:14]) + (f", other choice labels={rest} across {len(top) - 14} keys" if rest else ''))
    return rows

def main():
    ap = argparse.ArgumentParser(); ap.add_argument('out_dir'); ap.add_argument('--n', type=int, default=500); ap.add_argument('--seed', type=int, default=7)
    ap.add_argument('--families', default=','.join(FAMILIES)); ap.add_argument('--check', action='store_true'); a = ap.parse_args()
    out = Path(a.out_dir); out.mkdir(parents=True, exist_ok=True)
    if a.check: check(out); return
    R.seed(a.seed); fams = [f.strip() for f in a.families.split(',') if f.strip()]
    rows = generate(fams, a.n); seen = set(); uniq = []
    for r in rows:
        if r['group'] in seen: continue
        seen.add(r['group']); uniq.append(r)
    stats = collections.Counter((r['_family'], r['_sub'], r['_type'], r['_bal']) for r in uniq)
    train = [{k: v for k, v in r.items() if not k.startswith('_')} for r in uniq if r['upstream_split'] == 'train']; dev = [{k: v for k, v in r.items() if not k.startswith('_')} for r in uniq if r['upstream_split'] == 'dev']
    (out / 'train.jsonl').write_text('\n'.join(json.dumps(r, ensure_ascii=False) for r in train) + '\n'); (out / 'dev.jsonl').write_text('\n'.join(json.dumps(r, ensure_ascii=False) for r in dev) + '\n')
    summary = {'rows_per_family_requested': a.n, 'seed': a.seed, 'train_rows': len(train), 'dev_rows': len(dev), 'by_family': collections.Counter(r['_family'] for r in uniq),
               'by_subgenerator_type_balancekey': {f"{f}/{s}/{t}/{b}": c for (f, s, t, b), c in sorted(stats.items())}}
    (out / 'summary.json').write_text(json.dumps(summary, indent=1)); print(json.dumps({k: v for k, v in summary.items() if k != 'by_subgenerator_type_balancekey'}, indent=1))
    print(f"wrote {out / 'train.jsonl'} ({len(train)}) and {out / 'dev.jsonl'} ({len(dev)}); run with --check to verify overlap and balance")

if __name__ == '__main__': main()
